.wrapper {
    position: relative;
    padding: 64px;
    border-radius: 32px;
    border: 1px solid var(--border);
    background: linear-gradient(160deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.01));
    overflow: hidden;
    isolation: isolate;
}

.glow {
    position: absolute;
    z-index: -1;
    width: 600px;
    height: 600px;
    left: -200px;
    bottom: -300px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(34, 211, 238, 0.22), transparent 65%);
    filter: blur(40px);
    pointer-events: none;
}

.grid {
    position: relative;
    display: grid;
    grid-template-columns: 1fr 1.1fr;
    gap: 56px;
    align-items: start;
}

/* the heading lives in a narrower column here */
.intro > div:first-child { margin-bottom: 40px; }

.infoList {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    gap: 10px;
}

.infoItem {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 14px 16px;
    border-radius: 16px;
    border: 1px solid var(--border);
    background: var(--surface);
    color: var(--text);
    text-decoration: none;
    transition: border-color .3s, transform .3s var(--ease), background .3s;
}

a.infoItem:hover {
    color: var(--text);
    border-color: rgba(34, 211, 238, 0.45);
    background: var(--surface-2);
    transform: translateX(4px);
}

.infoIcon {
    flex-shrink: 0;
    width: 44px;
    height: 44px;
    border-radius: 12px;
    display: grid;
    place-items: center;
    color: var(--accent);
    background: rgba(34, 211, 238, 0.08);
    border: 1px solid rgba(34, 211, 238, 0.2);
}

.infoLabel {
    display: block;
    font-family: var(--font-mono);
    font-size: 11.5px;
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--text-dim);
}

.infoValue {
    display: block;
    font-size: 15.5px;
    font-weight: 500;
    word-break: break-word;
}

/* ---------- Form ---------- */
.formWrapper {
    padding: 32px;
    border-radius: 24px;
    background: rgba(7, 9, 13, 0.6);
    border: 1px solid var(--border-strong);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    box-shadow: 0 40px 80px -40px rgba(0, 0, 0, 0.8);
}

.row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}

.formGroup { margin-bottom: 18px; }

.formLabel {
    display: block;
    margin-bottom: 8px;
    font-size: 13px;
    font-weight: 500;
    color: var(--text-muted);
}

.formInput,
.formInput:global(.form-control),
.formInput:global(.form-select) {
    width: 100%;
    padding: 13px 16px;
    border-radius: 12px;
    border: 1px solid var(--border-strong);
    background-color: rgba(255, 255, 255, 0.03);
    color: var(--text);
    font-size: 15px;
    transition: border-color .25s, box-shadow .25s, background-color .25s;
}

.formInput:global(.form-select) {
    background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'%3e%3cpath fill='none' stroke='%238b94a7' stroke-linecap='round' stroke-linejoin='round' stroke-width='2' d='m2 5 6 6 6-6'/%3e%3c/svg%3e");
    background-repeat: no-repeat;
    background-position: right 16px center;
    background-size: 14px 10px;
}

.formInput:global(.form-select) option {
    background: #0e121a;
    color: var(--text);
}

.formInput::placeholder { color: var(--text-dim); }

.formInput:focus,
.formInput:global(.form-control):focus,
.formInput:global(.form-select):focus {
    outline: none;
    border-color: var(--accent);
    background-color: rgba(34, 211, 238, 0.04);
    box-shadow: 0 0 0 4px rgba(34, 211, 238, 0.12);
    color: var(--text);
}

.formInput:disabled { opacity: .6; }

.sendButton {
    position: relative;
    width: 100%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 6px;
    padding: 16px 24px;
    border: 0;
    border-radius: 14px;
    color: #05070a;
    background: var(--gradient);
    background-size: 200% 100%;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    transition: background-position .6s var(--ease), transform .3s var(--ease), box-shadow .3s;
}

.sendButton:hover:not(:disabled) {
    background-position: 100% 0;
    transform: translateY(-2px);
    box-shadow: 0 16px 40px -12px rgba(34, 211, 238, 0.6);
}

.sendButton svg { transition: transform .35s var(--ease); }
.sendButton:hover svg { transform: translate(3px, -3px); }
.sendButton:disabled { opacity: .7; cursor: wait; }

.spinner {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    border: 2px solid rgba(5, 7, 10, 0.3);
    border-top-color: #05070a;
    animation: spinSlow .7s linear infinite;
}

.statusMessage {
    margin-bottom: 20px;
    padding: 14px 16px;
    border-radius: 12px;
    font-size: 14px;
    animation: slideDown .4s var(--ease);
}

@keyframes slideDown {
    from { opacity: 0; transform: translateY(-8px); }
    to { opacity: 1; transform: none; }
}

.success {
    color: #6ee7b7;
    background: rgba(52, 211, 153, 0.08);
    border: 1px solid rgba(52, 211, 153, 0.3);
}

.error {
    color: #fca5a5;
    background: rgba(248, 113, 113, 0.08);
    border: 1px solid rgba(248, 113, 113, 0.3);
}

@media (max-width: 991.98px) {
    .wrapper { padding: 40px 28px; }
    .grid { grid-template-columns: 1fr; gap: 40px; }
}

@media (max-width: 575.98px) {
    .wrapper { padding: 32px 18px; border-radius: 24px; }
    .formWrapper { padding: 22px 18px; }
    .row { grid-template-columns: 1fr; gap: 0; }
}

/* local copies — CSS Modules scopes keyframe names */
@keyframes spinSlow { to { transform: rotate(360deg); } }
