.button {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 14px 26px;
    border-radius: 999px;
    border: 1px solid transparent;
    font-family: var(--font-sans);
    font-size: 15px;
    font-weight: 600;
    line-height: 1;
    cursor: pointer;
    overflow: hidden;
    isolation: isolate;
    transition: transform .3s var(--ease), box-shadow .3s var(--ease), background .3s, color .3s, border-color .3s;
}

.sm { padding: 10px 18px; font-size: 14px; }

.primary {
    color: #05070a;
    background: var(--text);
}

/* gradient wipe on hover */
.primary::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    background: var(--gradient);
    transform: translateX(-101%);
    transition: transform .5s var(--ease);
}

.primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 30px -8px rgba(34, 211, 238, 0.55);
}

.primary:hover::before { transform: none; }

.ghost {
    color: var(--text);
    background: var(--surface);
    border-color: var(--border-strong);
}

.ghost:hover {
    background: var(--surface-2);
    border-color: rgba(34, 211, 238, 0.5);
    transform: translateY(-2px);
}

.button:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 3px;
}

.icon {
    width: 18px;
    height: 18px;
    transition: transform .35s var(--ease);
}

.button:hover .icon { transform: translate(3px, -1px); }
