/* =========================================================
   Bento grid
   ┌───────────┬─────┬─────┐
   │           │ WP  │ CC  │
   │ featured  ├─────┼─────┤
   │           │ MVC │ RX  │
   └───────────┴─────┴─────┘
   ========================================================= */
.bento {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-template-areas:
        "feat feat a1 a2"
        "feat feat a3 a4";
    gap: 16px;
}

.featured { grid-area: feat; }
.area1 { grid-area: a1; }
.area2 { grid-area: a2; }
.area3 { grid-area: a3; }
.area4 { grid-area: a4; }

.card {
    display: flex;
    flex-direction: column;
    padding: 24px;
    overflow: hidden;
}

.card.in:hover {
    border-color: transparent;
    transform: translateY(-4px);
}

.cardTop {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 22px;
}

.iconTile {
    width: 56px;
    height: 56px;
    flex-shrink: 0;
    display: grid;
    place-items: center;
    border-radius: 16px;
    background:
        radial-gradient(circle at 30% 20%, rgba(34, 211, 238, 0.16), transparent 70%),
        rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(34, 211, 238, 0.22);
    box-shadow: 0 10px 30px -14px rgba(34, 211, 238, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.06);
    transition: transform .5s var(--ease), border-color .4s;
}

.card:hover .iconTile {
    transform: rotate(-6deg) scale(1.06);
    border-color: rgba(34, 211, 238, 0.5);
}

.name {
    margin: 0 0 8px;
    font-size: 19px;
    font-weight: 600;
    letter-spacing: -0.02em;
}

.description {
    margin: 12px 0 0;
    font-size: 14px;
    line-height: 1.6;
    color: var(--text-muted);
}

/* ---------- Level badge ---------- */
.level {
    align-self: flex-start;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    border-radius: 999px;
    font-family: var(--font-mono);
    font-size: 11px;
    letter-spacing: .06em;
    text-transform: uppercase;
    border: 1px solid;
}

.level::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: currentColor;
    box-shadow: 0 0 8px currentColor;
}

.lvlExpert { color: #34d399; border-color: rgba(52, 211, 153, .3); background: rgba(52, 211, 153, .08); }
.lvlAdvanced { color: #22d3ee; border-color: rgba(34, 211, 238, .3); background: rgba(34, 211, 238, .08); }
.lvlProficient { color: #818cf8; border-color: rgba(129, 140, 248, .3); background: rgba(129, 140, 248, .08); }
.lvlIntermediate { color: #c084fc; border-color: rgba(192, 132, 252, .3); background: rgba(192, 132, 252, .08); }

/* ---------- Ring gauge ---------- */
.gauge {
    position: relative;
    flex-shrink: 0;
    display: grid;
    place-items: center;
}

.gauge svg {
    position: absolute;
    inset: 0;
    overflow: visible;
}

.gaugeTrack {
    fill: none;
    stroke: rgba(255, 255, 255, 0.07);
}

.gaugeFill {
    fill: none;
    stroke-linecap: round;
    stroke-dashoffset: var(--c);
    transition: stroke-dashoffset 1.8s var(--ease) .3s;
    filter: drop-shadow(0 0 6px rgba(34, 211, 238, 0.45));
}

:global(.in) .gaugeFill { stroke-dashoffset: var(--off); }

.gaugeValue {
    position: relative;
    font-family: var(--font-display);
    font-size: 17px;
    font-weight: 600;
    letter-spacing: -0.03em;
}

.gaugeBig .gaugeValue {
    font-size: 44px;
    letter-spacing: -0.05em;
    background: linear-gradient(180deg, #fff, #9aa3b5);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

/* ---------- Featured card ---------- */
.featured {
    padding: 32px;
    min-height: 100%;
}

.featuredBg {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    background:
        radial-gradient(60% 55% at 85% 45%, rgba(34, 211, 238, 0.14), transparent 70%),
        radial-gradient(50% 50% at 10% 100%, rgba(129, 140, 248, 0.14), transparent 70%);
}

.featuredBody {
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: center;
    gap: 28px;
    margin-top: 6px;
}

.featuredName {
    margin: 0;
    font-size: clamp(1.6rem, 2.6vw, 2.2rem);
    font-weight: 600;
    letter-spacing: -0.03em;
}

.featured .description { font-size: 15px; max-width: 360px; }

.tags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin: 18px 0 0;
    padding: 0;
    list-style: none;
}

.tags li {
    padding: 5px 12px;
    border-radius: 999px;
    border: 1px solid var(--border-strong);
    background: var(--surface);
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--text);
}

.snippet {
    margin: auto 0 0;
    padding: 16px 18px;
    border-radius: 14px;
    border: 1px solid var(--border);
    background: rgba(0, 0, 0, 0.3);
    font-family: var(--font-mono);
    font-size: 12.5px;
    line-height: 1.9;
    color: var(--text-dim);
    overflow: hidden;
    white-space: pre;
    position: relative;
    top: 22px;
}

.snippet span {
    display: block;
    clip-path: inset(0 100% 0 0);
}

:global(.in) .snippet span { animation: typeLine .7s steps(28, end) forwards; }
:global(.in) .snippet span:nth-child(1) { animation-delay: .9s; }
:global(.in) .snippet span:nth-child(2) { animation-delay: 1.5s; }
:global(.in) .snippet span:nth-child(3) { animation-delay: 2.1s; }

@keyframes typeLine { to { clip-path: inset(0 0 0 0); } }

.snippet i { font-style: normal; color: #818cf8; }
.snippet b { font-weight: 400; color: #c084fc; }
.snippet em { font-style: normal; color: #34d399; }

/* ---------- Responsive ---------- */
@media (max-width: 1199.98px) {
    .bento {
        grid-template-columns: repeat(2, 1fr);
        grid-template-areas:
            "feat feat"
            "a1 a2"
            "a3 a4";
    }
    .snippet { top: 0; margin-top: 26px; }
}

@media (max-width: 575.98px) {
    .bento {
        grid-template-columns: 1fr;
        grid-template-areas: "feat" "a1" "a2" "a3" "a4";
    }

    .featured { padding: 24px; }

    .featuredBody {
        grid-template-columns: 1fr;
        justify-items: start;
    }

    .featuredBody .gauge { order: -1; width: 128px !important; height: 128px !important; }
    .featuredBody .gauge svg { width: 128px; height: 128px; }
    .gaugeBig .gaugeValue { font-size: 34px; }
}

@media (prefers-reduced-motion: reduce) {
    .snippet span { clip-path: none; }
}
