/* =========================================================
   Design tokens — dark, techy, minimal
   ========================================================= */
:root {
    --bg: #07090d;
    --bg-2: #0b0e14;
    --surface: rgba(255, 255, 255, 0.03);
    --surface-2: rgba(255, 255, 255, 0.06);
    --border: rgba(255, 255, 255, 0.08);
    --border-strong: rgba(255, 255, 255, 0.16);

    --text: #e7ebf2;
    --text-muted: #8b94a7;
    --text-dim: #5b6475;

    --accent: #22d3ee;          /* cyan */
    --accent-2: #818cf8;        /* indigo */
    --accent-3: #34d399;        /* green (status) */
    --gradient: linear-gradient(120deg, #22d3ee 0%, #818cf8 55%, #c084fc 100%);

    --font-sans: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-display: 'Space Grotesk', 'Inter', sans-serif;
    --font-mono: 'JetBrains Mono', ui-monospace, 'SFMono-Regular', monospace;

    --radius: 18px;
    --radius-sm: 12px;
    --ease: cubic-bezier(.2, .7, .2, 1);

    /* Bootstrap / CoreUI overrides */
    --cui-body-bg: var(--bg);
    --cui-body-color: var(--text);
    --bs-body-bg: var(--bg);
    --bs-body-color: var(--text);
    color-scheme: dark;
}

/* =========================================================
   Base
   ========================================================= */
html { scroll-behavior: smooth; scroll-padding-top: 84px; }

body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family: var(--font-sans);
    font-size: 16px;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-display);
    color: var(--text);
    letter-spacing: -0.02em;
}

a { color: var(--accent); }

::selection { background: rgba(34, 211, 238, 0.3); color: #fff; }

::-webkit-scrollbar { width: 10px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: #1f2532; border-radius: 10px; border: 2px solid var(--bg); }
::-webkit-scrollbar-thumb:hover { background: #2b3344; }

/* Ambient page background: faint grid + noise-like glow */
body::before {
    content: '';
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: -1;
    background:
        radial-gradient(60rem 40rem at 85% -10%, rgba(129, 140, 248, 0.10), transparent 60%),
        radial-gradient(50rem 35rem at -10% 30%, rgba(34, 211, 238, 0.07), transparent 60%),
        var(--bg);
}

.section {
    position: relative;
    padding: 88px 0;
    overflow-x: clip; /* slider peeks must never widen the page */
}

html, body { overflow-x: clip; }

@media (max-width: 768px) {
    .section { padding: 60px 0; }
}

.section-divider {
    height: 1px;
    max-width: 1200px;
    margin: 0 auto;
    background: linear-gradient(90deg, transparent, var(--border-strong), transparent);
}

.gradient-text {
    background: var(--gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

.mono { font-family: var(--font-mono); }

/* Grid backdrop used by hero / footer */
.grid-bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    background-image:
        linear-gradient(rgba(255, 255, 255, 0.045) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.045) 1px, transparent 1px);
    background-size: 64px 64px;
    -webkit-mask-image: radial-gradient(ellipse 70% 60% at 50% 40%, #000 30%, transparent 75%);
    mask-image: radial-gradient(ellipse 70% 60% at 50% 40%, #000 30%, transparent 75%);
}

/* =========================================================
   Card + cursor spotlight (pointer position set by useScrollReveal)
   ========================================================= */
.card-glass {
    position: relative;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.015));
    border: 1px solid var(--border);
    border-radius: var(--radius);
    transition: border-color .4s var(--ease), transform .4s var(--ease), background .4s var(--ease);
    isolation: isolate;
}

.spot::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    pointer-events: none;
    z-index: -1;
    opacity: 0;
    transition: opacity .4s var(--ease);
    background: radial-gradient(420px circle at var(--mx, 50%) var(--my, 50%), rgba(34, 211, 238, 0.10), transparent 45%);
}

.spot::after {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    pointer-events: none;
    padding: 1px;
    opacity: 0;
    transition: opacity .4s var(--ease);
    background: radial-gradient(280px circle at var(--mx, 50%) var(--my, 50%), rgba(34, 211, 238, 0.7), rgba(129, 140, 248, 0.35) 40%, transparent 70%);
    -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
}

.spot:hover::before,
.spot:hover::after { opacity: 1; }

/* =========================================================
   Scroll reveal (same system as the seat cushion page)
   ========================================================= */
.reveal {
    opacity: 0;
    transform: translateY(32px);
    transition: opacity 1s var(--ease), transform 1s var(--ease), filter 1s var(--ease);
    will-change: opacity, transform;
}
.reveal.in { opacity: 1; transform: none; }

.reveal[data-anim="left"]  { transform: translateX(-40px); }
.reveal[data-anim="right"] { transform: translateX(40px); }
.reveal[data-anim="zoom"]  { transform: scale(.94); filter: blur(6px); }
.reveal[data-anim="blur"]  { transform: translateY(16px); filter: blur(10px); }
.reveal[data-anim].in { transform: none; filter: none; }

.reveal[data-delay="1"] { transition-delay: .08s; }
.reveal[data-delay="2"] { transition-delay: .16s; }
.reveal[data-delay="3"] { transition-delay: .24s; }
.reveal[data-delay="4"] { transition-delay: .32s; }
.reveal[data-delay="5"] { transition-delay: .40s; }
.reveal[data-delay="6"] { transition-delay: .48s; }

.reveal.revealed {
    transition: opacity .4s var(--ease), transform .4s var(--ease), filter .4s var(--ease),
                border-color .4s var(--ease), background .4s var(--ease);
    will-change: auto;
}

/* Word-by-word headline reveal */
.w {
    display: inline-block;
    opacity: 0;
    transform: translateY(.45em);
    filter: blur(6px);
    transition: opacity .8s var(--ease), transform .8s var(--ease), filter .8s ease;
}
.in .w, .w.in { opacity: 1; transform: none; filter: none; }

/* Custom service icons: strokes draw on, dots pop in */
.svc-icon { overflow: visible; }
.svc-icon .d {
    fill: none;
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    transition: stroke-dashoffset 1.4s var(--ease) .25s;
}
.svc-icon .f {
    stroke: none;
    opacity: 0;
    transform-box: fill-box;
    transform-origin: center;
    transform: scale(0);
    transition: opacity .5s var(--ease) 1.1s, transform .5s cubic-bezier(.3, 1.6, .5, 1) 1.1s;
}
.svc-icon.animate .d { animation: svcDraw 1.2s var(--ease) .1s forwards; }
.svc-icon.animate .f { animation: svcPop .5s cubic-bezier(.3, 1.6, .5, 1) .9s forwards; }
@keyframes svcDraw { to { stroke-dashoffset: 0; } }
@keyframes svcPop { to { opacity: 1; transform: none; } }
.in .svc-icon .d, .svc-icon.drawn .d { stroke-dashoffset: 0; }
.in .svc-icon .f, .svc-icon.drawn .f { opacity: 1; transform: none; }

/* Scroll-linked progress bar */
.scroll-progress {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 2px;
    z-index: 2000;
    transform-origin: 0 50%;
    transform: scaleX(var(--progress, 0));
    background: var(--gradient);
    box-shadow: 0 0 12px rgba(34, 211, 238, 0.6);
}

@keyframes floatY {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-12px); }
}

@keyframes pulseDot {
    0% { box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.6); }
    100% { box-shadow: 0 0 0 10px rgba(52, 211, 153, 0); }
}

@keyframes spinSlow { to { transform: rotate(360deg); } }

@keyframes marquee {
    from { transform: translateX(0); }
    to { transform: translateX(-50%); }
}

@media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    .svc-icon .d { stroke-dashoffset: 0 !important; transition: none !important; }
    .svc-icon .f { opacity: 1 !important; transform: none !important; transition: none !important; }
    .reveal, .w { opacity: 1 !important; transform: none !important; filter: none !important; transition: none !important; }
    *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; }
}
