.grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
}

.card {
    padding: 28px 26px 30px;
    min-height: 280px;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.card.in:hover {
    transform: translateY(-6px);
    border-color: transparent;
}

.cardTop {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    margin-bottom: 36px;
}

.iconWrapper {
    width: 60px;
    height: 60px;
    border-radius: 16px;
    display: grid;
    place-items: center;
    background:
        radial-gradient(circle at 30% 20%, rgba(34, 211, 238, 0.16), transparent 70%),
        rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(34, 211, 238, 0.22);
    box-shadow: 0 10px 30px -14px rgba(34, 211, 238, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.06);
    transition: transform .5s var(--ease), border-color .4s, box-shadow .4s;
}

.card:hover .iconWrapper {
    transform: rotate(-6deg) scale(1.06);
    border-color: rgba(34, 211, 238, 0.5);
    box-shadow: 0 14px 36px -10px rgba(34, 211, 238, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.number {
    font-family: var(--font-mono);
    font-size: 13px;
    color: var(--text-dim);
    transition: color .3s;
}

.card:hover .number { color: var(--accent); }

.cardTitle {
    margin: 0 0 10px;
    font-size: 20px;
    font-weight: 600;
    letter-spacing: -0.02em;
}

.cardBody {
    margin: 0;
    font-size: 14.5px;
    line-height: 1.65;
    color: var(--text-muted);
}

.arrow {
    position: absolute;
    right: 22px;
    bottom: 22px;
    width: 34px;
    height: 34px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    color: var(--bg);
    background: var(--accent);
    opacity: 0;
    transform: translate(-8px, 8px) scale(.6);
    transition: opacity .4s var(--ease), transform .4s var(--ease);
}

.card:hover .arrow {
    opacity: 1;
    transform: none;
}

@media (max-width: 1199.98px) {
    .grid { grid-template-columns: repeat(2, 1fr); }
    .card { min-height: 0; }
}

@media (max-width: 575.98px) {
    .grid { grid-template-columns: 1fr; }
    .cardTop { margin-bottom: 24px; }
}
