.projectDetails {
    min-height: 100vh;
    padding-bottom: 80px;
}

/* ---------- Hero ---------- */
.heroSection {
    position: relative;
    min-height: 440px;
    display: flex;
    align-items: flex-end;
    padding: 150px 0 56px;
    border-bottom: 1px solid var(--border);
    overflow: hidden;
    background:
        radial-gradient(50rem 30rem at 80% 0%, rgba(129, 140, 248, 0.16), transparent 60%),
        radial-gradient(40rem 25rem at 10% 100%, rgba(34, 211, 238, 0.12), transparent 60%);
}

.particlesWrapper {
    position: absolute;
    inset: 0;
    z-index: 0;
    opacity: .7;
}

.heroOverlay {
    position: relative;
    z-index: 1;
    width: 100%;
}

.backButton {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 36px;
    padding: 8px 16px;
    border: 1px solid var(--border-strong);
    border-radius: 999px;
    background: rgba(7, 9, 13, 0.6);
    color: var(--text-muted);
    font-size: 14px;
    cursor: pointer;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    transition: all .25s var(--ease);
}

.backButton:hover {
    color: var(--text);
    border-color: var(--accent);
    transform: translateX(-3px);
}

.heroContent { max-width: 900px; }

.heroCategory {
    display: inline-block;
    margin-bottom: 18px;
    padding: 5px 12px;
    border-radius: 999px;
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--accent);
    background: rgba(34, 211, 238, 0.08);
    border: 1px solid rgba(34, 211, 238, 0.3);
}

.heroTitle {
    margin: 0;
    font-size: clamp(2.2rem, 5.5vw, 4.4rem);
    font-weight: 600;
    line-height: 1.05;
    letter-spacing: -0.04em;
}

.heroDate {
    margin-top: 18px;
    font-family: var(--font-mono);
    font-size: 13px;
    color: var(--text-dim);
}

/* ---------- Gallery ---------- */
.imageSliderSection {
    position: relative;
    margin-top: 48px;
}

.imageSwiper { padding-bottom: 4px; }

.slideItem {
    position: relative;
    aspect-ratio: 4 / 3;
    border-radius: var(--radius);
    overflow: hidden;
    border: 1px solid var(--border);
    background: #0e121a;
    cursor: zoom-in;
}

.slideItem img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: top;
    transition: transform .8s var(--ease);
}

.slideItem:hover img { transform: scale(1.05); }

.imageOverlay {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;
    background: rgba(7, 9, 13, 0.55);
    color: #fff;
    font-family: var(--font-mono);
    font-size: 12px;
    opacity: 0;
    backdrop-filter: blur(2px);
    transition: opacity .35s var(--ease);
}

.slideItem:hover .imageOverlay { opacity: 1; }

.navigationArrows {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    margin-top: 18px;
}

.navArrow {
    width: 46px;
    height: 46px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    border: 1px solid var(--border-strong);
    background: var(--surface);
    color: var(--text);
    cursor: pointer;
    transition: all .25s var(--ease);
}

.navArrow:hover {
    border-color: var(--accent);
    color: var(--accent);
    transform: translateY(-2px);
}

/* ---------- Description ---------- */
.descriptionSection { margin-top: 64px; }

.descriptionCard {
    padding: 48px;
    border-radius: 28px;
    border: 1px solid var(--border);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.01));
}

.descriptionHeader {
    margin-bottom: 28px;
}

.descriptionIcon {
    display: block;
    margin-bottom: 10px;
    font-family: var(--font-mono);
    font-size: 13px;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: .1em;
}

.descriptionHeader h2 {
    margin: 0;
    font-size: clamp(1.8rem, 3.5vw, 2.6rem);
    font-weight: 600;
}

.projectDescription {
    color: var(--text-muted);
    font-size: 16.5px;
    line-height: 1.8;
}

.paragraph { margin: 0 0 1.2em; }
.heading1, .heading2, .heading3, .heading4, .heading5, .heading6 {
    margin: 1.6em 0 .6em;
    color: var(--text);
}
.heading1 { font-size: 2rem; }
.heading2 { font-size: 1.7rem; }
.heading3 { font-size: 1.4rem; }
.heading4, .heading5, .heading6 { font-size: 1.15rem; }

.boldText { color: var(--text); font-weight: 600; }

.projectDescription code {
    padding: 2px 7px;
    border-radius: 6px;
    font-family: var(--font-mono);
    font-size: .86em;
    color: var(--accent);
    background: rgba(34, 211, 238, 0.08);
    border: 1px solid rgba(34, 211, 238, 0.18);
}
.italicText { font-style: italic; }
.underlineText { text-decoration-color: var(--accent); }

.blockquote {
    margin: 1.6em 0;
    padding: 4px 0 4px 20px;
    border-left: 2px solid var(--accent);
    color: var(--text);
    font-style: italic;
}

.unorderedList,
.orderedList {
    margin: 0 0 1.2em;
    padding-left: 1.3em;
}

.listItem { margin-bottom: .4em; }
.listItem p { margin: 0; }
.unorderedList .listItem::marker { color: var(--accent); }

.horizontalRule {
    margin: 2em 0;
    border: 0;
    height: 1px;
    background: var(--border-strong);
    opacity: 1;
}

.hyperlink {
    color: var(--accent);
    text-decoration: none;
    border-bottom: 1px solid rgba(34, 211, 238, 0.4);
    transition: border-color .2s;
}

.hyperlink:hover { color: var(--accent); border-color: var(--accent); }

.techSection {
    margin-top: 40px;
    padding-top: 28px;
    border-top: 1px solid var(--border);
}

.techSection h3 {
    margin: 0 0 16px;
    font-family: var(--font-mono);
    font-size: 13px;
    font-weight: 500;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--text-dim);
}

.tagsContainer {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.tag {
    padding: 7px 14px;
    border-radius: 999px;
    font-size: 13.5px;
    color: var(--text);
    background: var(--surface);
    border: 1px solid var(--border-strong);
    transition: all .25s var(--ease);
}

.tag:hover {
    border-color: var(--accent);
    color: var(--accent);
}

/* ---------- Loading / error ---------- */
.loadingContainer,
.errorContainer {
    min-height: 80vh;
    display: grid;
    place-items: center;
    padding: 120px 20px 40px;
    text-align: center;
}

.loader p {
    margin-top: 16px;
    font-family: var(--font-mono);
    font-size: 13px;
    color: var(--text-muted);
}

.spinner {
    width: 44px;
    height: 44px;
    margin: 0 auto;
    border-radius: 50%;
    border: 2px solid var(--border-strong);
    border-top-color: var(--accent);
    animation: spinSlow .8s linear infinite;
}

.errorContent h2 { margin: 12px 0 8px; }
.errorContent p { color: var(--text-muted); }
.errorIcon { font-size: 44px; }

.backHomeBtn {
    margin-top: 16px;
    padding: 12px 24px;
    border: 0;
    border-radius: 999px;
    background: var(--text);
    color: var(--bg);
    font-weight: 600;
    cursor: pointer;
}

/* ---------- Lightbox ---------- */
.lightbox {
    position: fixed;
    inset: 0;
    z-index: 3000;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 40px 80px;
    background: rgba(3, 4, 7, 0.92);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    animation: fadeIn .3s var(--ease);
}

@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

.lightboxContent {
    max-width: 1200px;
    max-height: 100%;
    display: flex;
    flex-direction: column;
    animation: zoomIn .4s var(--ease);
}

@keyframes zoomIn { from { transform: scale(.95); opacity: 0; } to { transform: none; opacity: 1; } }

.lightboxImage {
    max-width: 100%;
    max-height: calc(100vh - 140px);
    object-fit: contain;
    border-radius: 14px;
    border: 1px solid var(--border);
}

.lightboxInfo {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    margin-top: 14px;
    font-family: var(--font-mono);
    font-size: 13px;
    color: var(--text-muted);
}

.lightboxCounter { color: var(--accent); }

.lightboxClose,
.lightboxNav {
    position: absolute;
    display: grid;
    place-items: center;
    border: 1px solid var(--border-strong);
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.04);
    color: var(--text);
    cursor: pointer;
    transition: all .25s var(--ease);
}

.lightboxClose:hover,
.lightboxNav:hover {
    border-color: var(--accent);
    color: var(--accent);
}

.lightboxClose { top: 24px; right: 24px; width: 46px; height: 46px; }
.lightboxNav { top: 50%; width: 54px; height: 54px; transform: translateY(-50%); }
.lightboxPrev { left: 20px; }
.lightboxNext { right: 20px; }

@media (max-width: 767.98px) {
    .heroSection { min-height: 360px; padding: 120px 0 40px; }
    .descriptionCard { padding: 28px 22px; border-radius: 22px; }
    .lightbox { padding: 70px 12px; }
    .lightboxNav { top: auto; bottom: 16px; transform: none; width: 46px; height: 46px; }
    .lightboxPrev { left: calc(50% - 56px); }
    .lightboxNext { right: calc(50% - 56px); }
}

/* local copies — CSS Modules scopes keyframe names */
@keyframes spinSlow { to { transform: rotate(360deg); } }
