/* =========================================================
   Scroll container + sticky stage
   ========================================================= */
.wrap {
    position: relative;
    height: 480vh;
    /* trim the empty band the centered sticky stage leaves above / below its content */
    margin: -8vh 0 -12vh;
    --ry: 200deg;
    --rx: 14deg;
    --rz: 0deg;
    --spin: 0;
    --land: 0;
    --power: 0;
    --enter: 0;

    /* phone geometry */
    --ph: min(600px, 70vh);
    --pw: calc(var(--ph) * .49);
    --pd: calc(var(--pw) * .1);          /* thickness */
    --pr: calc(var(--pw) * .165);        /* corner radius */
    --bez: calc(var(--pw) * .032);       /* black bezel */
}

.stage {
    position: sticky;
    top: 0;
    height: 100vh;
    max-width: 1240px;
    margin: 0 auto;
    padding: 80px 24px 0;
    display: grid;
    grid-template-columns: 1fr 1.05fr;
    align-items: center;
    gap: 40px;
    overflow: hidden;
    /* the stage overlaps neighbouring sections' padding — let clicks pass through */
    pointer-events: none;
}

.copy,
.phoneScene { pointer-events: auto; }

.halo {
    position: absolute;
    right: 8%;
    top: 50%;
    width: calc(var(--ph) * 1.2);
    height: calc(var(--ph) * 1.2);
    transform: translateY(-45%);
    border-radius: 50%;
    background:
        radial-gradient(closest-side, rgba(129, 140, 248, calc(.12 + var(--power) * .14)), transparent 70%),
        radial-gradient(closest-side at 40% 60%, rgba(244, 114, 182, calc(var(--land) * .18)), transparent 70%);
    filter: blur(30px);
    pointer-events: none;
}

/* ---------- Caption ---------- */
.copy {
    position: relative;
    z-index: 2;
    max-width: 520px;
}

.eyebrow {
    margin: 0 0 16px;
    font-family: var(--font-mono);
    font-size: 13px;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--accent);
    animation: copyIn .6s var(--ease) both;
}

.title {
    margin: 0;
    font-size: clamp(2.2rem, 4.6vw, 3.8rem);
    font-weight: 600;
    line-height: 1.04;
    letter-spacing: -0.04em;
    animation: copyIn .7s var(--ease) .06s both;
}

.text {
    margin: 22px 0 0;
    font-size: 17px;
    line-height: 1.7;
    color: var(--text-muted);
    animation: copyIn .7s var(--ease) .12s both;
}

.chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin: 26px 0 0;
    padding: 0;
    list-style: none;
}

.chips li {
    padding: 7px 14px;
    border-radius: 999px;
    border: 1px solid var(--border-strong);
    background: var(--surface);
    font-family: var(--font-mono);
    font-size: 12.5px;
    color: var(--text);
    animation: copyIn .5s var(--ease) both;
}

@keyframes copyIn {
    from { opacity: 0; transform: translateY(14px); filter: blur(6px); }
    to { opacity: 1; transform: none; filter: none; }
}

.steps {
    display: flex;
    gap: 22px;
    margin-top: 40px;
    padding-top: 22px;
    border-top: 1px solid var(--border);
}

.steps span {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 14px;
    color: var(--text-dim);
    transition: color .3s;
}

.steps i {
    font-style: normal;
    font-family: var(--font-mono);
    font-size: 11px;
    padding: 3px 7px;
    border-radius: 6px;
    border: 1px solid var(--border);
    transition: all .3s;
}

.steps .stepOn { color: var(--text); }
.steps .stepOn i { color: var(--bg); background: var(--accent); border-color: var(--accent); }

/* =========================================================
   3D phone
   ========================================================= */
.phoneScene {
    position: relative;
    z-index: 1;
    justify-self: center;
    width: var(--pw);
    height: var(--ph);
    perspective: 1800px;
    opacity: calc(.2 + var(--enter) * .8);
}

.floater {
    width: 100%;
    height: 100%;
    transform-style: preserve-3d;
    animation: floaty 6s ease-in-out infinite;
}

@keyframes floaty {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-10px); }
}

.phone {
    position: relative;
    width: 100%;
    height: 100%;
    transform-style: preserve-3d;
    transform:
        translateY(calc((1 - var(--enter)) * 30%))
        scale(calc(.86 + var(--spin) * .14 - var(--land) * .1))
        rotateX(var(--rx))
        rotateY(var(--ry))
        rotateZ(var(--rz));
    /* no opacity here: opacity < 1 flattens preserve-3d and breaks depth sorting */
}

/* Frame: stacked slabs with a natural-titanium sheen */
.layer {
    position: absolute;
    inset: 0;
    border-radius: var(--pr);
    transform: translateZ(calc(var(--z) * var(--pd)));
    background: linear-gradient(90deg, #5f656f 0%, #c7ccd4 12%, #8d939c 30%, #6d737c 50%, #9aa0a8 70%, #d3d7dd 88%, #5c626b 100%);
    box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .25);
}

/* side buttons protrude slightly from the frame */
.btn {
    position: absolute;
    width: calc(var(--pw) * .016);
    border-radius: 3px;
    background: linear-gradient(90deg, #6a7079, #d1d5db 50%, #7b818a);
    transform: translateZ(0);
}

.btnAction { left: calc(var(--pw) * -.012); top: 17%; height: 4.5%; }
.btnVolUp { left: calc(var(--pw) * -.012); top: 25%; height: 8%; }
.btnVolDown { left: calc(var(--pw) * -.012); top: 35%; height: 8%; }
.btnPower { right: calc(var(--pw) * -.012); top: 28%; height: 12%; }

/* ---------- Back: frosted glass + camera plateau ---------- */
.back {
    position: absolute;
    inset: 0;
    border-radius: var(--pr);
    transform: translateZ(calc(var(--pd) * -.5 - .5px)) rotateY(180deg);
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    transform-style: preserve-3d;
    background:
        radial-gradient(90% 60% at 30% 15%, rgba(255, 255, 255, .14), transparent 60%),
        radial-gradient(80% 50% at 80% 100%, rgba(129, 140, 248, .18), transparent 70%),
        linear-gradient(160deg, #2a3346 0%, #1a2130 55%, #121722 100%);
    box-shadow: inset 0 0 0 calc(var(--pw) * .012) #7d838c, inset 0 0 0 calc(var(--pw) * .016) rgba(0, 0, 0, .4);
}

.camModule {
    position: absolute;
    top: 4.5%;
    left: 6%;
    width: 46%;
    aspect-ratio: 1;
    border-radius: 27%;
    transform: translateZ(2px);
    background: linear-gradient(150deg, rgba(255, 255, 255, .12), rgba(255, 255, 255, .03)), #1f2838;
    box-shadow:
        inset 0 0 0 1px rgba(255, 255, 255, .14),
        0 4px 12px rgba(0, 0, 0, .5);
}

.lens {
    position: absolute;
    width: 42%;
    aspect-ratio: 1;
    border-radius: 50%;
    background:
        radial-gradient(circle at 36% 34%, rgba(160, 200, 255, .8) 0 5%, transparent 9%),
        radial-gradient(circle at 60% 64%, rgba(192, 132, 252, .35) 0 6%, transparent 12%),
        radial-gradient(circle, #233759 0 22%, #0a0f1c 38%, #05070c 62%, #20242c 64%, #0d1015 72%);
    box-shadow:
        0 0 0 calc(var(--pw) * .008) #8f959e,
        0 0 0 calc(var(--pw) * .012) #3a3f47,
        0 3px 8px rgba(0, 0, 0, .7);
}

.lens1 { top: 6%; left: 6%; }
.lens2 { bottom: 6%; left: 6%; }
.lens3 { top: 29%; right: 6%; }

.flash {
    position: absolute;
    top: 12%;
    right: 14%;
    width: 13%;
    aspect-ratio: 1;
    border-radius: 50%;
    background: radial-gradient(circle, #fff6d8, #d9c48a 60%, #6b6040);
}

.lidar {
    position: absolute;
    bottom: 14%;
    right: 16%;
    width: 10%;
    aspect-ratio: 1;
    border-radius: 50%;
    background: radial-gradient(circle, #3a3f49, #0b0d11);
}

.backLogo {
    position: absolute;
    left: 50%;
    top: 52%;
    transform: translate(-50%, -50%);
    font-family: var(--font-display);
    font-weight: 700;
    font-size: calc(var(--pw) * .13);
    letter-spacing: -0.04em;
    background: linear-gradient(135deg, #f4f7fb, #8d96a6 50%, #dfe5ee);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    opacity: .7;
}

/* ---------- Front: bezel + screen ---------- */
.front {
    position: absolute;
    inset: 0;
    border-radius: var(--pr);
    padding: var(--bez);
    transform: translateZ(calc(var(--pd) * .5 + .5px));
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    background: #030304;
    box-shadow: inset 0 0 0 calc(var(--pw) * .006) #2a2e35;
}

/* Chrome composites animated children (wallpaper, canvas…) on their own layers,
   which ignore the parent's backface-visibility — so hide every descendant too */
.front *,
.back * {
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
}

.screen {
    position: relative;
    width: 100%;
    height: 100%;
    border-radius: calc(var(--pr) - var(--bez));
    overflow: hidden;
    background: #000;
    container-type: inline-size;
}

.island {
    position: absolute;
    z-index: 8;
    top: calc(var(--pw) * .028);
    left: 50%;
    width: 33%;
    height: calc(var(--pw) * .095);
    transform: translateX(-50%);
    border-radius: 999px;
    background: #000;
    pointer-events: none;
}

.island i {
    position: absolute;
    right: 14%;
    top: 50%;
    width: calc(var(--pw) * .042);
    height: calc(var(--pw) * .042);
    transform: translateY(-50%);
    border-radius: 50%;
    background: radial-gradient(circle at 40% 40%, #24324d, #07090e 65%);
}

.glass {
    position: absolute;
    inset: 0;
    z-index: 9;
    pointer-events: none;
    background: linear-gradient(120deg, transparent 20%, rgba(255, 255, 255, .1) 32%, rgba(255, 255, 255, .02) 42%, transparent 55%);
    background-size: 260% 100%;
    background-position: calc(50% + var(--ryn, 0) * 1.2%) 0;
    mix-blend-mode: screen;
}

.off {
    position: absolute;
    inset: 0;
    z-index: 7;
    background: #000;
    opacity: calc(1 - var(--power));
    pointer-events: none;
}

.screenLayer {
    position: absolute;
    inset: 0;
    opacity: 0;
    visibility: hidden;
    transition: opacity .5s var(--ease), visibility .5s;
}

.screenLayer.on { opacity: 1; visibility: visible; }

/* landscape layer: rotated 90° inside the portrait screen, so it reads upright
   when the whole phone turns to landscape */
.landscape {
    inset: auto;
    top: 50%;
    left: 50%;
    width: calc(var(--ph) - var(--bez) * 2);
    height: calc(var(--pw) - var(--bez) * 2);
    transform: translate(-50%, -50%) rotate(90deg);
}

.shadow {
    position: absolute;
    left: 50%;
    bottom: -9%;
    width: calc(var(--pw) * (1.1 + var(--land) * .9));
    height: 7%;
    transform: translateX(-50%);
    border-radius: 50%;
    background: radial-gradient(closest-side, rgba(0, 0, 0, .7), transparent);
    filter: blur(12px);
    opacity: var(--enter);
}

/* =========================================================
   Lock screen
   ========================================================= */
.lock {
    position: absolute;
    inset: 0;
    color: #fff;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.wallpaper {
    position: absolute;
    inset: -20%;
    background:
        radial-gradient(40% 35% at 30% 30%, rgba(34, 211, 238, .75), transparent 70%),
        radial-gradient(45% 40% at 75% 55%, rgba(129, 140, 248, .8), transparent 70%),
        radial-gradient(40% 35% at 40% 85%, rgba(244, 114, 182, .6), transparent 70%),
        #0b0b1e;
    filter: blur(10px) saturate(1.2);
    animation: aurora 12s ease-in-out infinite alternate;
}

@keyframes aurora {
    from { transform: rotate(0deg) scale(1); }
    to { transform: rotate(25deg) scale(1.15); }
}

.lockTop {
    position: relative;
    margin-top: 20cqw;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.lockDate {
    font-size: 4.6cqw;
    font-weight: 500;
    opacity: .85;
}

.lockTime {
    font-family: var(--font-display);
    font-size: 25cqw;
    font-weight: 600;
    line-height: 1;
    letter-spacing: -0.04em;
    text-shadow: 0 2cqw 6cqw rgba(0, 0, 0, .25);
}

.lockNotif {
    position: relative;
    margin-top: auto;
    margin-bottom: 6cqw;
    width: 90%;
    display: flex;
    gap: 3cqw;
    padding: 3.4cqw;
    border-radius: 6cqw;
    background: rgba(255, 255, 255, .16);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, .18);
    opacity: 0;
    transform: translateY(6cqw) scale(.96);
}

.on .lockNotif { animation: notifIn .7s cubic-bezier(.3, 1.3, .5, 1) .5s forwards; }

@keyframes notifIn { to { opacity: 1; transform: none; } }

.notifIcon {
    flex-shrink: 0;
    width: 10cqw;
    height: 10cqw;
    display: grid;
    place-items: center;
    border-radius: 2.6cqw;
    background: var(--gradient);
    color: #05070a;
    font-family: var(--font-display);
    font-weight: 700;
    font-size: 3.8cqw;
}

.notifBody { display: flex; flex-direction: column; font-size: 3.5cqw; line-height: 1.35; }
.notifBody b { display: flex; justify-content: space-between; font-weight: 600; }
.notifBody em { font-style: normal; opacity: .6; font-weight: 400; }

.lockBottom {
    position: relative;
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 9cqw 5cqw;
}

.lockBtn {
    width: 12cqw;
    height: 12cqw;
    display: grid;
    place-items: center;
    border-radius: 50%;
    background: rgba(0, 0, 0, .3);
    backdrop-filter: blur(10px);
}

.lockBtn svg { width: 5cqw; height: 5cqw; }

.homeBar {
    position: absolute;
    left: 50%;
    bottom: 2.4cqw;
    width: 36%;
    height: 1.3cqw;
    transform: translateX(-50%);
    border-radius: 2cqw;
    background: rgba(255, 255, 255, .85);
}

/* =========================================================
   Game (landscape)
   ========================================================= */
.gameLayer {
    position: absolute;
    inset: 0;
    background: #070a16;
}

.canvas {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: fill;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    user-select: none;
}

/* while playing, finger drags steer the ship instead of scrolling the page */
.playing .canvas {
    touch-action: none;
    cursor: crosshair;
}

.joystick,
.fireBtn,
.gameTag { pointer-events: none; }

.exitBtn {
    position: absolute;
    top: 5%;
    right: 3.5%;
    width: calc(var(--pw) * .085);
    height: calc(var(--pw) * .085);
    display: grid;
    place-items: center;
    padding: 0;
    border: 1px solid rgba(255, 255, 255, .25);
    border-radius: 50%;
    background: rgba(0, 0, 0, .55);
    color: #fff;
    font-size: calc(var(--pw) * .035);
    cursor: pointer;
    z-index: 2;
}

.exitBtn:hover { border-color: var(--accent); color: var(--accent); }

.gameTag {
    position: absolute;
    top: 6%;
    left: 50%;
    transform: translateX(-50%);
    padding: .4em 1em;
    border-radius: 999px;
    background: rgba(0, 0, 0, .45);
    border: 1px solid rgba(255, 255, 255, .12);
    font-family: var(--font-mono);
    font-size: calc(var(--pw) * .028);
    letter-spacing: .08em;
    color: rgba(255, 255, 255, .7);
    white-space: nowrap;
}

.joystick {
    position: absolute;
    left: 10%;
    bottom: 10%;
    width: calc(var(--pw) * .2);
    aspect-ratio: 1;
    border-radius: 50%;
    border: 1.5px solid rgba(255, 255, 255, .2);
    background: rgba(255, 255, 255, .04);
}

.joystick i {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 42%;
    aspect-ratio: 1;
    border-radius: 50%;
    background: rgba(255, 255, 255, .22);
    transform: translate(-50%, -50%);
    animation: stick 2.4s ease-in-out infinite;
}

@keyframes stick {
    0%, 100% { transform: translate(-50%, -80%); }
    50% { transform: translate(-50%, -20%); }
}

.fireBtn {
    position: absolute;
    right: 7%;
    bottom: 12%;
    width: calc(var(--pw) * .16);
    aspect-ratio: 1;
    display: grid;
    place-items: center;
    border-radius: 50%;
    border: 1.5px solid rgba(34, 211, 238, .5);
    background: rgba(34, 211, 238, .12);
    font-family: var(--font-mono);
    font-size: calc(var(--pw) * .028);
    color: rgba(255, 255, 255, .8);
    animation: firePulse .28s ease-in-out infinite alternate;
}

@keyframes firePulse {
    from { transform: scale(1); box-shadow: 0 0 0 rgba(34, 211, 238, 0); }
    to { transform: scale(.94); box-shadow: 0 0 18px rgba(34, 211, 238, .5); }
}

/* =========================================================
   Fitness app (portrait)
   ========================================================= */
.app {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    gap: 3cqw;
    padding: 0 4.5cqw;
    background:
        radial-gradient(80% 40% at 100% 0%, rgba(129, 140, 248, .25), transparent 70%),
        #07080d;
    color: #fff;
    font-size: 3.4cqw;
}

.statusBar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 13cqw;
    padding: 0 3cqw;
    font-weight: 600;
    font-size: 3.6cqw;
}

.statusIcons { display: flex; align-items: flex-end; gap: .7cqw; }
.statusIcons i { width: .9cqw; background: #fff; border-radius: 1px; }
.statusIcons i:nth-child(1) { height: 1.4cqw; }
.statusIcons i:nth-child(2) { height: 2.1cqw; }
.statusIcons i:nth-child(3) { height: 2.8cqw; }
.statusIcons b { width: 5.5cqw; height: 2.6cqw; margin-left: 1cqw; border-radius: .8cqw; border: 1px solid rgba(255, 255, 255, .6); background: linear-gradient(90deg, #fff 75%, transparent 75%); background-clip: content-box; padding: 1px; }

.appHead {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.appHead span:first-child { display: flex; flex-direction: column; }
.appHead em { font-style: normal; font-size: 3.4cqw; color: rgba(255, 255, 255, .55); }
.appHead b { font-family: var(--font-display); font-size: 6.4cqw; font-weight: 600; letter-spacing: -0.02em; }

.avatar {
    width: 10cqw;
    height: 10cqw;
    display: grid;
    place-items: center;
    border-radius: 50%;
    background: var(--gradient);
    color: #05070a;
    font-weight: 700;
}

.ringCard,
.statCard,
.chartCard {
    border-radius: 5cqw;
    background: rgba(255, 255, 255, .05);
    border: 1px solid rgba(255, 255, 255, .07);
}

.ringCard {
    display: flex;
    align-items: center;
    gap: 4cqw;
    padding: 4cqw;
}

.rings { width: 34cqw; height: 34cqw; flex-shrink: 0; }

.rings circle[style] { stroke-dashoffset: var(--c); }
.on .rings circle[style] { animation: ringFill 1.4s var(--ease) forwards; }

@keyframes ringFill {
    from { stroke-dashoffset: var(--c); }
    to { stroke-dashoffset: var(--off); }
}

.ringStats { display: flex; flex-direction: column; gap: 2.2cqw; font-size: 3cqw; color: rgba(255, 255, 255, .6); }
.ringStats span { display: flex; flex-direction: column; }
.ringStats i { display: inline-block; width: 2cqw; height: 2cqw; border-radius: 50%; margin-right: 1.4cqw; }
.ringStats b { color: #fff; font-size: 3.8cqw; font-weight: 600; }

.statRow { display: grid; grid-template-columns: 1fr 1fr; gap: 3cqw; }

.statCard {
    position: relative;
    padding: 3.6cqw 4cqw;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.statCard em { font-style: normal; font-size: 3cqw; color: rgba(255, 255, 255, .55); }
.statCard b { font-family: var(--font-display); font-size: 6cqw; font-weight: 600; }
.statCard small { font-size: 3cqw; color: rgba(255, 255, 255, .5); font-weight: 400; }

.spark svg { width: 100%; height: 6cqw; margin-top: 1cqw; }
.spark path { stroke-dasharray: 1; stroke-dashoffset: 1; }
.on .spark path { animation: draw 1.2s var(--ease) .6s forwards; }

@keyframes draw { to { stroke-dashoffset: 0; } }

.heart {
    position: absolute;
    right: 4cqw;
    top: 3.4cqw;
    color: #f472b6;
    font-size: 5cqw;
    animation: beat 1s ease-in-out infinite;
}

@keyframes beat {
    0%, 100% { transform: scale(1); }
    15% { transform: scale(1.25); }
    30% { transform: scale(1); }
    45% { transform: scale(1.15); }
}

.chartCard { padding: 4cqw; }

.chartHead { display: flex; justify-content: space-between; align-items: center; margin-bottom: 3cqw; }
.chartHead b { font-weight: 600; font-size: 3.8cqw; }
.chartHead em { font-style: normal; font-size: 3cqw; color: #34d399; }

.bars {
    display: flex;
    align-items: flex-end;
    gap: 2.4cqw;
    height: 22cqw;
}

.bars span {
    flex: 1;
    height: calc(var(--h) * 100%);
    border-radius: 1.4cqw;
    background: rgba(255, 255, 255, .12);
    transform-origin: bottom;
    transform: scaleY(0);
}

.bars .barActive { background: var(--gradient); box-shadow: 0 0 4cqw rgba(34, 211, 238, .4); }

.on .bars span { animation: grow .7s cubic-bezier(.3, 1.3, .5, 1) forwards; }

@keyframes grow { to { transform: scaleY(1); } }

.days {
    display: flex;
    gap: 2.4cqw;
    margin-top: 1.6cqw;
    font-size: 2.6cqw;
    color: rgba(255, 255, 255, .45);
}

.days span { flex: 1; text-align: center; }

.tabBar {
    margin-top: auto;
    margin-bottom: 6cqw;
    display: flex;
    justify-content: space-around;
    padding: 3cqw;
    border-radius: 7cqw;
    background: rgba(255, 255, 255, .07);
    border: 1px solid rgba(255, 255, 255, .08);
    color: rgba(255, 255, 255, .45);
}

.tabBar svg { width: 5.6cqw; height: 5.6cqw; }

.tabActive {
    color: #05070a;
    background: var(--accent);
    border-radius: 50%;
    padding: 1.6cqw;
    margin: -1.6cqw;
}

.appToast {
    position: absolute;
    top: 4cqw;
    left: 50%;
    width: 84%;
    display: flex;
    align-items: center;
    gap: 2.4cqw;
    padding: 2.6cqw 3.6cqw;
    border-radius: 6cqw;
    background: #000;
    border: 1px solid rgba(255, 255, 255, .1);
    font-size: 3cqw;
    color: rgba(255, 255, 255, .75);
    transform: translate(-50%, -150%) scale(.6);
    opacity: 0;
    z-index: 3;
}

.appToast b { color: #fff; }

/* dynamic-island style expand */
.on .appToast { animation: islandToast 4s var(--ease) 1.6s forwards; }

@keyframes islandToast {
    0% { opacity: 0; transform: translate(-50%, -150%) scale(.6); }
    12% { opacity: 1; transform: translate(-50%, 0) scale(1); }
    80% { opacity: 1; transform: translate(-50%, 0) scale(1); }
    100% { opacity: 0; transform: translate(-50%, -150%) scale(.6); }
}

/* =========================================================
   Responsive
   ========================================================= */
@media (max-width: 991.98px) {
    .wrap {
        height: 440vh;
        --ph: min(440px, 52vh);
        /* stacked layout fills the bottom of the stage — don't pull the next section up */
        margin: -4vh 0 0;
    }

    .stage {
        grid-template-columns: 1fr;
        grid-template-rows: auto 1fr;
        align-content: center;
        gap: 20px;
        padding: 76px 16px 0;
    }

    .copy {
        order: 2;
        max-width: none;
        text-align: center;
    }

    .phoneScene { order: 1; }

    .phone {
        transform:
            translateY(calc((1 - var(--enter)) * 30%))
            scale(calc(.86 + var(--spin) * .14 - var(--land) * .26))
            rotateX(var(--rx))
            rotateY(var(--ry))
            rotateZ(var(--rz));
    }

    .title { font-size: clamp(1.7rem, 7vw, 2.4rem); }
    .text { font-size: 14.5px; margin-top: 12px; }
    .chips { justify-content: center; margin-top: 14px; }
    .chips li { font-size: 11px; padding: 5px 11px; }
    .steps { display: none; }
    .halo { right: 50%; transform: translate(50%, -60%); }
}
