/* ---------- Header arrows ---------- */
.navigation {
    display: flex;
    gap: 10px;
}

.navBtn {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    border: 1px solid var(--border-strong);
    background: var(--surface);
    color: var(--text);
    cursor: pointer;
    transition: all .3s var(--ease);
}

.navBtn:hover {
    border-color: var(--accent);
    color: var(--accent);
    transform: translateY(-2px);
}

/* ---------- Moving track ----------
   Full-bleed (breaks out of the container) with faded edges. */
.viewport {
    position: relative;
    margin-inline: calc(50% - 50vw);
    padding: 36px 0 28px;
    overflow: hidden;
    cursor: grab;
    touch-action: pan-y;          /* vertical page scroll still works on touch */
    user-select: none;
    -webkit-mask-image: linear-gradient(90deg, transparent 0, #000 14%, #000 86%, transparent 100%);
    mask-image: linear-gradient(90deg, transparent 0, #000 14%, #000 86%, transparent 100%);
}

.grabbing { cursor: grabbing; }

.track {
    display: flex;
    align-items: center;
    gap: 22px;
    width: max-content;
    will-change: transform;
}

/* ---------- Card with focus effect ----------
   --f is set every frame: 1 = centred (in focus), 0 = off to the side. */
.card {
    --f: 0;
    flex-shrink: 0;
    width: clamp(290px, 30vw, 390px);
    margin: 0;
    padding: 28px;
    display: flex;
    flex-direction: column;
    min-height: 300px;
    transform: scale(calc(.86 + var(--f) * .14));
    opacity: calc(.32 + var(--f) * .68);
    filter: saturate(calc(.35 + var(--f) * .65));
    border-color: rgba(255, 255, 255, calc(.06 + var(--f) * .1));
    background:
        radial-gradient(90% 70% at 50% 0%, rgba(34, 211, 238, calc(var(--f) * .1)), transparent 70%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.015));
    box-shadow: 0 40px 90px -40px rgba(34, 211, 238, calc(var(--f) * .55));
    /* the frame loop drives these — no CSS transition on them */
    transition: none;
}

/* animated gradient edge that fades in only on the focused card */
.card::after {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    padding: 1px;
    pointer-events: none;
    background: linear-gradient(135deg, rgba(34, 211, 238, .9), rgba(129, 140, 248, .5) 40%, transparent 60%, rgba(192, 132, 252, .7));
    -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    opacity: calc(var(--f) * var(--f));
}

.top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    margin-bottom: 18px;
}

.stars {
    display: flex;
    gap: 2px;
    color: #fbbf24;
    filter: drop-shadow(0 0 calc(var(--f) * 6px) rgba(251, 191, 36, .6));
}

.stars svg { width: 16px; height: 16px; }

.quoteMark {
    font-family: var(--font-display);
    font-size: 72px;
    line-height: .6;
    background: var(--gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    transform: scale(calc(.8 + var(--f) * .3)) rotate(calc((1 - var(--f)) * -12deg));
    transform-origin: top right;
    filter: drop-shadow(0 0 calc(var(--f) * 14px) rgba(129, 140, 248, .7));
}

.quote {
    margin: 0 0 26px;
    font-size: 16px;
    line-height: 1.7;
    color: var(--text);
    opacity: calc(.7 + var(--f) * .3);
}

.person {
    margin-top: auto;
    display: flex;
    align-items: center;
    gap: 12px;
    padding-top: 18px;
    border-top: 1px solid var(--border);
}

.avatar {
    width: 46px;
    height: 46px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid rgba(34, 211, 238, calc(.15 + var(--f) * .6));
    box-shadow: 0 0 0 calc(var(--f) * 4px) rgba(34, 211, 238, .12);
    pointer-events: none;
}

.name {
    margin: 0;
    font-size: 15px;
    font-weight: 600;
    color: var(--text);
}

.role {
    margin: 0;
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--text-dim);
}

/* ---------- Dots ---------- */
.dots {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-top: 18px;
}

.dot {
    width: 8px;
    height: 8px;
    padding: 0;
    border: 0;
    border-radius: 999px;
    background: rgba(255, 255, 255, .18);
    cursor: pointer;
    transition: width .4s var(--ease), background .3s;
}

.dot:hover { background: rgba(255, 255, 255, .4); }

.dotActive {
    width: 28px;
    background: var(--gradient);
    box-shadow: 0 0 12px rgba(34, 211, 238, .5);
}

@media (max-width: 575.98px) {
    .card { width: 82vw; padding: 22px; min-height: 0; }
    .quote { font-size: 15px; }
    .viewport {
        -webkit-mask-image: linear-gradient(90deg, transparent 0, #000 6%, #000 94%, transparent 100%);
        mask-image: linear-gradient(90deg, transparent 0, #000 6%, #000 94%, transparent 100%);
    }
}
