.timeline {
    position: relative;
    list-style: none;
    margin: 0;
    padding: 0;
    --line: 0;
    --gap: 48px; /* space between card and the center line */
}

.track {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 50%;
    width: 1px;
    background: var(--border);
    transform: translateX(-50%);
}

.fill {
    position: absolute;
    inset: 0;
    transform-origin: top;
    transform: scaleY(var(--line));
    background: linear-gradient(180deg, var(--accent), var(--accent-2));
    box-shadow: 0 0 12px rgba(34, 211, 238, 0.6);
}

/* Each entry: [card] [line] [side info] — flipped on even rows */
.item {
    position: relative;
    display: grid;
    grid-template-columns: 1fr 1fr;
    column-gap: calc(var(--gap) * 2);
    align-items: center;
    padding: 14px 0;
}

.card { grid-column: 1; grid-row: 1; padding: 26px 28px; }
.side { grid-column: 2; grid-row: 1; }

.flip .card { grid-column: 2; }
.flip .side { grid-column: 1; text-align: right; align-items: flex-end; }

.card.in:hover {
    border-color: transparent;
    transform: translateY(-4px);
}

/* ---------- Center node ---------- */
.node {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 14px;
    height: 14px;
    margin: -7px 0 0 -7px;
    border-radius: 50%;
    background: var(--bg);
    border: 2px solid var(--accent);
    box-shadow: 0 0 0 6px var(--bg), 0 0 16px rgba(34, 211, 238, 0.7);
    z-index: 1;
}

/* connector from node toward the card */
.node::before {
    content: '';
    position: absolute;
    top: 50%;
    right: calc(100% + 6px);
    width: calc(var(--gap) - 14px);
    height: 1px;
    background: linear-gradient(270deg, rgba(34, 211, 238, 0.6), transparent);
}

.flip .node::before {
    right: auto;
    left: calc(100% + 6px);
    background: linear-gradient(90deg, rgba(34, 211, 238, 0.6), transparent);
}

.nodeCurrent::after {
    content: '';
    position: absolute;
    inset: -2px;
    border-radius: 50%;
    animation: pulseRing 2s ease-out infinite;
    border: 2px solid var(--accent);
}

@keyframes pulseRing {
    from { transform: scale(1); opacity: .9; }
    to { transform: scale(2.6); opacity: 0; }
}

/* ---------- Side info (fills the empty half) ---------- */
.side {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
}

.sideIndex {
    font-family: var(--font-mono);
    font-size: 12px;
    letter-spacing: .1em;
    color: var(--text-dim);
}

.years {
    font-family: var(--font-display);
    font-size: clamp(2.6rem, 5vw, 4.4rem);
    font-weight: 600;
    line-height: 1;
    letter-spacing: -0.05em;
    background: linear-gradient(180deg, rgba(231, 235, 242, .55), rgba(231, 235, 242, .06));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    transition: background .5s var(--ease);
}

.item:hover .years {
    background-image: linear-gradient(180deg, rgba(34, 211, 238, .9), rgba(129, 140, 248, .15));
}

.duration {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-top: 6px;
    padding: 5px 12px;
    border-radius: 999px;
    border: 1px solid var(--border);
    background: var(--surface);
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--text-muted);
}

.durationDot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--accent);
    box-shadow: 0 0 8px var(--accent);
}

/* ---------- Card content ---------- */
.cardHead {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 12px;
}

.period {
    font-family: var(--font-mono);
    font-size: 12.5px;
    color: var(--accent);
}

.badge {
    padding: 3px 10px;
    border-radius: 999px;
    font-family: var(--font-mono);
    font-size: 11px;
    color: var(--accent-3);
    background: rgba(52, 211, 153, 0.1);
    border: 1px solid rgba(52, 211, 153, 0.3);
}

.role {
    margin: 0;
    font-size: 22px;
    font-weight: 600;
}

.company {
    margin: 4px 0 12px;
    font-size: 14px;
    color: var(--text);
    opacity: .75;
}

.description {
    margin: 0;
    font-size: 15px;
    color: var(--text-muted);
}

/* ---------- Mobile: single column, side info becomes a compact header ---------- */
@media (max-width: 767.98px) {
    .track { left: 7px; }
    .node { left: 7px; top: 34px; }
    .node::before { display: none; }

    .item,
    .flip.item {
        grid-template-columns: 1fr;
        row-gap: 10px;
        padding: 18px 0 18px 36px;
    }

    .side,
    .flip .side {
        grid-column: 1;
        grid-row: 1;
        flex-direction: row;
        align-items: center;
        text-align: left;
        gap: 12px;
    }

    .card,
    .flip .card { grid-column: 1; grid-row: 2; }

    .sideIndex { display: none; }
    .years { font-size: 2rem; }
    .duration { margin-top: 0; }
}
