.navigation {
    display: flex;
    gap: 10px;
}

.navBtn {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    border: 1px solid var(--border-strong);
    background: var(--surface);
    color: var(--text);
    cursor: pointer;
    transition: all .3s var(--ease);
}

.navBtn:hover {
    border-color: var(--accent);
    color: var(--accent);
    transform: translateY(-2px);
}

.navBtn:global(.swiper-button-disabled) {
    opacity: .3;
    cursor: not-allowed;
}

/* peek upcoming slides on the right, hide passed ones on the left */
.slider { overflow: visible; clip-path: inset(-40px -100vw -40px 0); }
.slider :global(.swiper-wrapper) { align-items: stretch; }
.slide { height: auto; }

.card {
    height: 100%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    color: inherit;
    text-decoration: none;
}

.card:hover { color: inherit; }

.card.in:hover {
    border-color: transparent;
    transform: translateY(-4px);
}

.imageWrapper {
    position: relative;
    margin: 8px 8px 0;
    aspect-ratio: 16 / 9;
    border-radius: 12px;
    overflow: hidden;
    background: #121826;
}

.image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform .8s var(--ease);
}

.card:hover .image { transform: scale(1.06); }

.source {
    position: absolute;
    top: 12px;
    left: 12px;
    padding: 5px 11px;
    border-radius: 999px;
    font-family: var(--font-mono);
    font-size: 11px;
    color: var(--text);
    background: rgba(7, 9, 13, 0.7);
    border: 1px solid var(--border-strong);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
}

.content {
    display: flex;
    flex-direction: column;
    flex: 1;
    padding: 20px 22px 22px;
}

.date {
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--accent);
    margin-bottom: 10px;
}

.title {
    margin: 0 0 10px;
    font-size: 18px;
    font-weight: 600;
    line-height: 1.35;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.description {
    margin: 0 0 18px;
    font-size: 14px;
    line-height: 1.6;
    color: var(--text-muted);
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.readMore {
    margin-top: auto;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 14px;
    font-weight: 500;
}

.readMore svg {
    color: var(--accent);
    transition: transform .35s var(--ease);
}

.card:hover .readMore svg { transform: translate(3px, -3px); }

/* Skeleton */
.skeletonGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
}

.skeletonCard {
    border-radius: var(--radius);
    border: 1px solid var(--border);
    overflow: hidden;
}

.skeletonImage,
.skeletonTitle,
.skeletonText,
.skeletonLink {
    background: linear-gradient(100deg, rgba(255, 255, 255, 0.03) 30%, rgba(255, 255, 255, 0.08) 50%, rgba(255, 255, 255, 0.03) 70%);
    background-size: 300% 100%;
    animation: shimmer 1.6s linear infinite;
    border-radius: 8px;
}

.skeletonImage { aspect-ratio: 16 / 9; border-radius: 0; }
.skeletonContent { padding: 20px; }
.skeletonTitle { height: 20px; width: 80%; margin-bottom: 14px; }
.skeletonText { height: 56px; margin-bottom: 14px; }
.skeletonLink { height: 14px; width: 30%; }

@keyframes shimmer {
    from { background-position: 100% 0; }
    to { background-position: -100% 0; }
}

@media (max-width: 991.98px) {
    .skeletonGrid { grid-template-columns: 1fr 1fr; }
    .skeletonGrid > :nth-child(3) { display: none; }
}

@media (max-width: 575.98px) {
    .skeletonGrid { grid-template-columns: 1fr; }
    .skeletonGrid > :nth-child(2) { display: none; }
}
