.hero {
    position: relative;
    min-height: 100vh;
    padding: 150px 0 0;
    overflow: hidden;
    --px: 0;
    --py: 0;
}

.inner { position: relative; z-index: 2; }

/* Mouse-follow glow */
.glow {
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: radial-gradient(600px circle at var(--gx, 70%) var(--gy, 30%), rgba(34, 211, 238, 0.08), transparent 45%);
    transition: background .2s;
}

.orb {
    position: absolute;
    border-radius: 50%;
    filter: blur(90px);
    pointer-events: none;
    opacity: .55;
}

.orb1 {
    width: 480px;
    height: 480px;
    top: -120px;
    right: -80px;
    background: radial-gradient(circle, #6366f1, transparent 70%);
    transform: translate(calc(var(--px) * -40px), calc(var(--py) * -40px));
    animation: drift 14s ease-in-out infinite alternate;
}

.orb2 {
    width: 420px;
    height: 420px;
    bottom: 40px;
    left: -160px;
    background: radial-gradient(circle, #0891b2, transparent 70%);
    transform: translate(calc(var(--px) * 30px), calc(var(--py) * 30px));
    animation: drift 18s ease-in-out infinite alternate-reverse;
    opacity: .4;
}

@keyframes drift {
    from { translate: 0 0; }
    to { translate: 60px 40px; }
}

.grid {
    display: grid;
    grid-template-columns: 1.15fr 1fr;
    align-items: center;
    gap: 48px;
}

/* ---------- Copy ---------- */
.status {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 7px 14px 7px 10px;
    margin: 0 0 28px;
    border: 1px solid var(--border-strong);
    border-radius: 999px;
    background: var(--surface);
    font-family: var(--font-mono);
    font-size: 12.5px;
    color: var(--text-muted);
}

.statusDot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--accent-3);
    animation: pulseDot 1.8s ease-out infinite;
}

.title {
    margin: 0;
    font-weight: 600;
    letter-spacing: -0.04em;
    line-height: 1;
}

.hello {
    display: block;
    font-size: clamp(1.25rem, 2.2vw, 1.6rem);
    font-weight: 500;
    color: var(--text-muted);
    letter-spacing: -0.01em;
    margin-bottom: 16px;
}

.headline {
    display: block;
    font-size: clamp(2.8rem, 7vw, 5.6rem);
}

.typeWrap {
    display: inline-flex;
    align-items: baseline;
    white-space: nowrap;
}

.caret {
    display: inline-block;
    width: 0.06em;
    height: 0.8em;
    margin-left: 6px;
    background: var(--accent);
    box-shadow: 0 0 12px var(--accent);
    animation: blink 1s steps(1) infinite;
}

@keyframes blink { 50% { opacity: 0; } }

.body {
    max-width: 540px;
    margin: 28px 0 0;
    font-size: 18px;
    line-height: 1.7;
    color: var(--text-muted);
}

.actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 36px;
}

.meta {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 40px;
    font-size: 13px;
    color: var(--text-dim);
}

.metaSep {
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--text-dim);
}

/* ---------- Visual ---------- */
.visual {
    position: relative;
    justify-self: center;
    width: min(100%, 440px);
    aspect-ratio: 900 / 1050;
    perspective: 1200px;
}

/* 3D tilt toward the mouse (--px / --py come from the hero's pointer handler).
   Depth is set with the `translate` property so it composes with each layer's
   own animated `transform`. */
.tilt {
    position: absolute;
    inset: 0;
    transform-style: preserve-3d;
    transform: rotateY(calc(var(--px) * 14deg)) rotateX(calc(var(--py) * -10deg));
    transition: transform .4s var(--ease);
}

/* ---- backdrop card ---- */
.card {
    position: absolute;
    left: 0;
    right: 0;
    top: 22%;
    bottom: 0;
    border-radius: 32px;
    overflow: hidden;
    background:
        radial-gradient(90% 70% at 50% 100%, rgba(34, 211, 238, 0.28), transparent 65%),
        radial-gradient(70% 60% at 85% 10%, rgba(129, 140, 248, 0.22), transparent 70%),
        linear-gradient(180deg, #111725 0%, #0a0e16 100%);
    border: 1px solid var(--border-strong);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.08),
        0 40px 120px -40px rgba(34, 211, 238, 0.45);
}

.cardGrid {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
    background-size: 28px 28px;
    -webkit-mask-image: radial-gradient(ellipse 80% 70% at 50% 40%, #000 20%, transparent 80%);
    mask-image: radial-gradient(ellipse 80% 70% at 50% 40%, #000 20%, transparent 80%);
}

.cardGlow {
    position: absolute;
    left: 10%;
    right: 10%;
    bottom: -30%;
    height: 60%;
    border-radius: 50%;
    background: radial-gradient(closest-side, rgba(34, 211, 238, 0.5), rgba(129, 140, 248, 0.2) 50%, transparent);
    filter: blur(20px);
    animation: glowPulse 5s ease-in-out infinite alternate;
}

@keyframes glowPulse {
    from { opacity: .7; transform: scale(.95); }
    to { opacity: 1; transform: scale(1.05); }
}

/* one-off light sweep across the card after it appears */
.sweep {
    position: absolute;
    top: 0;
    bottom: 0;
    left: -60%;
    width: 50%;
    background: linear-gradient(100deg, transparent, rgba(255, 255, 255, 0.12), transparent);
    transform: skewX(-12deg);
    animation: sweep 1.6s var(--ease) 1.1s both;
}

@keyframes sweep {
    from { left: -60%; }
    to { left: 130%; }
}

.cardMeta {
    position: absolute;
    font-family: var(--font-mono);
    font-size: 10.5px;
    letter-spacing: .12em;
    color: rgba(231, 235, 242, 0.4);
}

.metaTL { top: 16px; left: 20px; }

@media (max-width: 640px) {
    .cardMeta { display: none; }
}
.metaBR { top: 16px; right: 44px; }

.corner {
    position: absolute;
    top: 14px;
    right: 16px;
    width: 18px;
    height: 18px;
    border-top: 1.5px solid var(--accent);
    border-right: 1.5px solid var(--accent);
    border-radius: 0 6px 0 0;
    opacity: .7;
}

/* soft halo behind the head, above the card's top edge */
.headGlow {
    position: absolute;
    left: 22%;
    right: 22%;
    top: 2%;
    height: 40%;
    border-radius: 50%;
    background: radial-gradient(closest-side, rgba(129, 140, 248, 0.45), rgba(34, 211, 238, 0.15) 60%, transparent);
    filter: blur(26px);
    translate: 0 0 10px;
}

.picture { display: contents; }

/* ---- the cutout: rises out of the card ---- */
.photo {
    position: absolute;
    left: 50%;
    bottom: 0;
    width: 96%;
    height: auto;
    transform: translateX(-50%);
    translate: 0 0 40px;
    /* blend the hard bottom crop into the card */
    -webkit-mask-image: linear-gradient(to bottom, #000 82%, transparent 100%);
    mask-image: linear-gradient(to bottom, #000 82%, transparent 100%);
    filter:
        drop-shadow(0 0 1px rgba(34, 211, 238, 0.35))
        drop-shadow(0 24px 40px rgba(0, 0, 0, 0.55));
    animation: photoRise 1.1s var(--ease) .35s both;
    user-select: none;
    -webkit-user-drag: none;
}

@keyframes photoRise {
    from { opacity: 0; transform: translateX(-50%) translateY(8%) scale(.97); }
    to { opacity: 1; transform: translateX(-50%); }
}

.ring,
.ring2 {
    position: absolute;
    z-index: 1;
    border-radius: 50%;
    pointer-events: none;
}

.ring {
    inset: 4% -16% -6%;
    border: 1px dashed rgba(34, 211, 238, 0.28);
    animation: spinSlow 40s linear infinite;
    translate: 0 0 -40px;
}

.ring2 {
    inset: 14% -4% 4%;
    border: 1px solid rgba(129, 140, 248, 0.18);
    animation: spinSlow 60s linear infinite reverse;
    translate: 0 0 -20px;
}

.ring::after {
    content: '';
    position: absolute;
    top: 50%;
    left: -5px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--accent);
    box-shadow: 0 0 18px var(--accent);
}

.chip {
    position: absolute;
    z-index: 3;
    background: rgba(11, 14, 20, 0.78);
    border: 1px solid var(--border-strong);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    box-shadow: 0 20px 50px -20px rgba(0, 0, 0, 0.8);
    translate: 0 0 80px; /* floats in front of the photo when tilting */
}

.chipCode {
    top: 10%;
    left: -12%;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 16px;
    border-radius: 12px;
    font-family: var(--font-mono);
    animation: floatY 6s ease-in-out infinite;
}

.chipCode code {
    color: var(--accent);
    font-size: 14px;
}

.chipDot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--accent-2);
    box-shadow: 0 0 10px var(--accent-2);
}

.review {
    right: -10%;
    bottom: 8%;
    width: 260px;
    padding: 16px 18px;
    border-radius: 16px;
    animation: floatY 7s ease-in-out .8s infinite;
}

.stars {
    display: flex;
    align-items: center;
    gap: 2px;
    color: #fbbf24;
}

.stars svg { width: 15px; height: 15px; }

.stars span {
    margin-left: 8px;
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--text-muted);
}

.reviewTitle {
    margin: 10px 0 4px;
    font-family: var(--font-display);
    font-weight: 600;
    font-size: 15px;
    color: var(--text);
}

.reviewText {
    margin: 0;
    font-size: 13px;
    line-height: 1.5;
    color: var(--text-muted);
}

/* ---------- Stats ---------- */
.stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-top: 90px;
}

.stat {
    display: flex;
    align-items: center;
    gap: 18px;
    padding: 26px 28px;
}

.statValue {
    font-family: var(--font-display);
    font-size: clamp(2.4rem, 4vw, 3.4rem);
    font-weight: 600;
    line-height: 1;
    letter-spacing: -0.04em;
    background: linear-gradient(180deg, #fff, #8b94a7);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    min-width: 2.2ch;
}

.statLabel {
    font-size: 14px;
    color: var(--text-muted);
    max-width: 120px;
    line-height: 1.4;
}

/* ---------- Marquee ---------- */
.marquee {
    position: relative;
    z-index: 2;
    margin-top: 80px;
    padding: 22px 0;
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
    overflow: hidden;
    -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);
    mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);
}

.track {
    display: flex;
    width: max-content;
    animation: marquee 40s linear infinite;
}

.marquee:hover .track { animation-play-state: paused; }

.tech {
    display: inline-flex;
    align-items: center;
    gap: 14px;
    padding: 0 28px;
    font-family: var(--font-display);
    font-size: 20px;
    font-weight: 500;
    color: var(--text-dim);
    white-space: nowrap;
    transition: color .3s;
}

.tech:hover { color: var(--text); }

.techDot {
    color: var(--accent);
    font-size: 12px;
}

/* ---------- Responsive ---------- */
@media (max-width: 991.98px) {
    .hero { padding-top: 120px; }

    .grid {
        grid-template-columns: 1fr;
        gap: 72px;
    }

    .visual { width: min(80%, 380px); }
    .chipCode { left: -6%; }
    .review { right: -6%; }

    .stats { margin-top: 72px; }
}

@media (max-width: 640px) {
    .body { font-size: 16px; }

    .stats {
        grid-template-columns: 1fr;
        gap: 12px;
    }

    .stat { padding: 20px 22px; }

    .visual { width: 82%; }
    .review { width: 220px; right: -8%; bottom: -6%; }
    .chipCode { top: 4%; left: -8%; padding: 8px 12px; }
    .chipCode code { font-size: 12px; }

    .meta { flex-wrap: wrap; gap: 8px 14px; }

    .tech { font-size: 16px; padding: 0 18px; }
}

/* local copies — CSS Modules scopes keyframe names */
@keyframes spinSlow { to { transform: rotate(360deg); } }
@keyframes floatY {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-12px); }
}
@keyframes pulseDot {
    0% { box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.6); }
    100% { box-shadow: 0 0 0 10px rgba(52, 211, 153, 0); }
}
@keyframes marquee {
    from { transform: translateX(0); }
    to { transform: translateX(-50%); }
}
