.footer {
    position: relative;
    margin-top: 40px;
    padding: 80px 0 32px;
    border-top: 1px solid var(--border);
    overflow: hidden;
}

.inner { position: relative; z-index: 1; }

.top {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 40px;
    flex-wrap: wrap;
}

.logo {
    height: 40px;
    width: auto;
    cursor: pointer;
}

.tagline {
    max-width: 340px;
    margin: 18px 0 0;
    font-size: 15px;
    color: var(--text-muted);
}

.nav {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.navLink {
    padding: 8px 16px;
    border: 1px solid var(--border);
    border-radius: 999px;
    background: var(--surface);
    color: var(--text-muted);
    font-size: 14px;
    cursor: pointer;
    transition: all .25s var(--ease);
}

.navLink:hover {
    color: var(--text);
    border-color: rgba(34, 211, 238, 0.45);
    transform: translateY(-2px);
}

.bigText {
    margin: 64px 0 24px;
    font-family: var(--font-display);
    font-weight: 700;
    font-size: clamp(3rem, 11vw, 10rem);
    line-height: .9;
    letter-spacing: -0.05em;
    white-space: nowrap;
    text-align: center;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0.01));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    user-select: none;
}

.bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px 24px;
    padding-top: 24px;
    border-top: 1px solid var(--border);
    font-family: var(--font-mono);
    font-size: 12.5px;
    color: var(--text-dim);
}

.toTop {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 0;
    border: 0;
    background: none;
    color: var(--text-muted);
    font: inherit;
    cursor: pointer;
    transition: color .25s;
}

.toTop:hover { color: var(--accent); }
.toTop svg { transition: transform .3s var(--ease); }
.toTop:hover svg { transform: translateY(-3px); }

@media (max-width: 767.98px) {
    .bigText { font-size: 15vw; white-space: normal; }
    .bottom { flex-direction: column; align-items: flex-start; }
}
