/* =========================================================
   Scroll container + sticky stage
   ========================================================= */
.wrap {
    position: relative;
    height: 520vh;
    --p: 0;
    --open: 0;
    --boot: 0;
    --intro: 1;
    --sp: 0;
    /* laptop width: limited by viewport width AND height */
    --w: min(800px, 90vw, calc((100vh - 290px) * .96));
}

.stage {
    position: sticky;
    top: 0;
    height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 28px;
    overflow: hidden;
    padding-top: 64px;
}

.halo {
    position: absolute;
    left: 50%;
    top: 46%;
    width: calc(var(--w) * 1.3);
    height: calc(var(--w) * .8);
    transform: translate(-50%, -50%);
    border-radius: 50%;
    background: radial-gradient(closest-side, rgba(34, 211, 238, .22), rgba(129, 140, 248, .12) 55%, transparent);
    filter: blur(30px);
    opacity: calc(var(--boot) * .9);
    pointer-events: none;
}

/* ---------- Intro ---------- */
.intro {
    position: absolute;
    top: 15vh;
    left: 0;
    right: 0;
    z-index: 3;
    text-align: center;
    padding: 0 16px;
    opacity: var(--intro);
    transform: translateY(calc((1 - var(--intro)) * -40px)) scale(calc(.94 + var(--intro) * .06));
    pointer-events: none;
}

.eyebrow {
    margin: 0 0 14px;
    font-family: var(--font-mono);
    font-size: 13px;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--accent);
}

.introTitle {
    margin: 0;
    font-size: clamp(2rem, 5.4vw, 4.4rem);
    font-weight: 600;
    line-height: 1.05;
    letter-spacing: -0.04em;
}

.scrollHint {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    margin: 26px 0 0;
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--text-dim);
}

.mouse {
    position: relative;
    width: 18px;
    height: 28px;
    border: 1.5px solid var(--text-dim);
    border-radius: 10px;
}

.mouse span {
    position: absolute;
    left: 50%;
    top: 5px;
    width: 2px;
    height: 6px;
    margin-left: -1px;
    border-radius: 2px;
    background: var(--accent);
    animation: wheel 1.6s ease-in-out infinite;
}

@keyframes wheel {
    0% { opacity: 0; transform: translateY(0); }
    30% { opacity: 1; }
    100% { opacity: 0; transform: translateY(9px); }
}

/* =========================================================
   3D laptop
   ========================================================= */
.scene {
    position: relative;
    z-index: 2;
    width: var(--w);
    height: calc(var(--w) * .62);
    perspective: 2600px;
    perspective-origin: 50% -30%;
    flex-shrink: 0;
    /* room for the base, which is drawn in 3D below this box */
    margin-bottom: calc(var(--w) * .31);
}

.laptop {
    position: relative;
    width: 100%;
    height: 100%;
    transform-style: preserve-3d;
    transform:
        translateY(calc((1 - var(--open)) * 22%))
        rotateX(calc(-34deg + var(--open) * 22deg))
        scale(calc(.74 + var(--open) * .26));
}

/* ---------- Materials ---------- */
.laptop {
    --t: calc(var(--w) * .0085);            /* lid thickness */
    --bt: calc(var(--w) * .021);            /* base thickness */
    --radius: calc(var(--w) * .022);
    /* anodised space-grey aluminium with a fine brushed grain */
    --alu:
        repeating-linear-gradient(90deg, rgba(255, 255, 255, .018) 0 1px, transparent 1px 3px),
        linear-gradient(160deg, #3b424e 0%, #2a3039 45%, #1f242c 100%);
}

/* Lid — hinged on its bottom edge, opens to ~102° */
.lid {
    position: absolute;
    inset: 0;
    transform-style: preserve-3d;
    transform-origin: 50% 100%;
    transform: rotateX(calc(-90deg + var(--open) * 102deg));
}

.lidBack,
.screenFace {
    position: absolute;
    inset: 0;
    border-radius: var(--radius) var(--radius) calc(var(--radius) * .35) calc(var(--radius) * .35);
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
}

/* back panel sits one lid-thickness behind the screen */
.lidBack {
    transform: translateZ(calc(var(--t) * -1)) rotateX(180deg);
    display: grid;
    place-items: center;
    background:
        /* moving specular highlight as the lid swings */
        radial-gradient(70% 60% at calc(25% + var(--open) * 50%) calc(15% + var(--open) * 40%), rgba(255, 255, 255, .16), transparent 60%),
        var(--alu);
    box-shadow:
        inset 0 0 0 1px rgba(255, 255, 255, .06),
        inset 0 1px 0 rgba(255, 255, 255, .14);
}

.lidLogo {
    width: 11%;
    filter: drop-shadow(0 0 1px rgba(255, 255, 255, .35)) drop-shadow(0 1px 1px rgba(0, 0, 0, .6));
    opacity: .85;
}

/* lid edges (give the lid real depth when it's tilted) */
.lidEdgeTop,
.lidEdgeLeft,
.lidEdgeRight {
    position: absolute;
    background: linear-gradient(90deg, #1d222a, #4a5260 50%, #1d222a);
}

.lidEdgeTop {
    left: var(--radius);
    right: var(--radius);
    top: 0;
    height: var(--t);
    transform-origin: 50% 0;
    transform: rotateX(-90deg);
}

.lidEdgeLeft,
.lidEdgeRight {
    top: var(--radius);
    bottom: 0;
    width: var(--t);
    background: linear-gradient(180deg, #4a5260, #262b33);
}

.lidEdgeLeft { left: 0; transform-origin: 0 50%; transform: rotateY(90deg); }
.lidEdgeRight { right: 0; transform-origin: 100% 50%; transform: rotateY(-90deg); }

/* ---------- Screen: glass, thin black bezel, aluminium rim ---------- */
.screenFace {
    padding: 2.4% 1.7% 2.2%;
    background: #050608;
    box-shadow:
        0 0 0 calc(var(--w) * .0035) #2b313b,                  /* aluminium rim */
        0 0 0 calc(var(--w) * .0045) rgba(255, 255, 255, .08), /* chamfer highlight */
        0 30px 90px -30px rgba(34, 211, 238, calc(var(--boot) * .55));
}

.camera {
    position: absolute;
    top: .8%;
    left: 50%;
    width: calc(var(--w) * .011);
    height: calc(var(--w) * .011);
    transform: translateX(-50%);
    border-radius: 50%;
    background: radial-gradient(circle at 35% 35%, #2c3a55, #0b0f18 60%);
    box-shadow: 0 0 0 1px #11151c;
}

.camera i {
    position: absolute;
    left: 28%;
    top: 26%;
    width: 22%;
    height: 22%;
    border-radius: 50%;
    background: rgba(140, 180, 255, .55);
}

/* glossy glass reflection over the whole face, slides as the lid opens */
.glass {
    position: absolute;
    inset: 0;
    z-index: 6;
    border-radius: inherit;
    pointer-events: none;
    background:
        linear-gradient(118deg,
            rgba(255, 255, 255, 0) 0%,
            rgba(255, 255, 255, .09) 18%,
            rgba(255, 255, 255, .02) 30%,
            rgba(255, 255, 255, 0) 45%);
    background-size: 220% 100%;
    background-position: calc(100% - var(--open) * 70%) 0;
    mix-blend-mode: screen;
}

.display {
    position: relative;
    width: 100%;
    height: 100%;
    border-radius: calc(var(--w) * .006);
    overflow: hidden;
    background: #020305;
    container-type: inline-size;
}

.screenGlare { display: none; }

.screenContent {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    opacity: var(--boot);
    filter: brightness(calc(.4 + var(--boot) * .6));
    background:
        radial-gradient(80% 60% at 80% 0%, rgba(129, 140, 248, .14), transparent 60%),
        linear-gradient(180deg, #0a0d14, #07090d);
}

/* ---------- Base (deck) ---------- */
.base {
    position: absolute;
    left: 0;
    right: 0;
    top: calc(100% + var(--t) * .6);
    height: calc(var(--w) * .64);
    transform-origin: 50% 0;
    transform: rotateX(90deg);
    transform-style: preserve-3d;
    border-radius: calc(var(--radius) * .35) calc(var(--radius) * .35) var(--radius) var(--radius);
    background:
        radial-gradient(90% 60% at 50% 100%, rgba(255, 255, 255, .07), transparent 70%),
        var(--alu);
    box-shadow:
        inset 0 0 0 1px rgba(255, 255, 255, .07),
        inset 0 -1px 0 rgba(255, 255, 255, .18);
}

/* screen light spilling onto the deck */
.lightSpill {
    position: absolute;
    inset: 0;
    border-radius: inherit;
    pointer-events: none;
    background: radial-gradient(70% 45% at 50% 0%, rgba(34, 211, 238, calc(var(--boot) * .22)), rgba(129, 140, 248, calc(var(--boot) * .08)) 50%, transparent 75%);
}

.hinge {
    position: absolute;
    left: 13%;
    right: 13%;
    top: 0;
    height: 2.4%;
    border-radius: 0 0 6px 6px;
    background: linear-gradient(180deg, #050608, #161a21 70%, #2a303a);
}

.speaker {
    position: absolute;
    top: 6.5%;
    height: 47%;
    width: 7%;
    border-radius: 4px;
    background-image: radial-gradient(circle, rgba(0, 0, 0, .85) 40%, transparent 46%);
    background-size: calc(var(--w) * .0085) calc(var(--w) * .0085);
    opacity: .9;
}

.speakerL { left: 2.6%; }
.speakerR { right: 2.6%; }

/* keyboard well: backlight glows through the gaps between keys */
.keyboard {
    position: absolute;
    left: 11%;
    right: 11%;
    top: 6%;
    height: 48%;
    padding: .55%;
    display: flex;
    flex-direction: column;
    gap: 1.6%;
    border-radius: 6px;
    background:
        radial-gradient(80% 90% at 50% 50%, rgba(34, 211, 238, calc(var(--boot) * .35)), transparent 75%),
        #07080b;
    box-shadow: inset 0 1px 3px rgba(0, 0, 0, .9), 0 1px 0 rgba(255, 255, 255, .06);
}

.keyRow {
    flex: 1;
    display: flex;
    gap: .55%;
}

.fnRow { flex: .62; }

.key {
    position: relative;
    flex: 1 1 0;
    min-width: 0;
    display: grid;
    place-items: center;
    border-radius: calc(var(--w) * .003);
    background: linear-gradient(180deg, #1c2028 0%, #14171d 100%);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, .07),
        inset 0 -1px 0 rgba(0, 0, 0, .6);
}

.key em {
    font-style: normal;
    font-family: var(--font-sans);
    font-size: calc(var(--w) * .0105);
    line-height: 1;
    color: rgba(220, 230, 245, calc(.32 + var(--boot) * .45));
    text-shadow: 0 0 calc(var(--boot) * 6px) rgba(34, 211, 238, calc(var(--boot) * .9));
    user-select: none;
}

.key em.small { font-size: calc(var(--w) * .0078); }

.arrowStack {
    flex: 1 1 0;
    display: flex;
    flex-direction: column;
    gap: 6%;
}

.arrowStack .key em { font-size: calc(var(--w) * .006); }

.trackpad {
    position: absolute;
    left: 29%;
    right: 29%;
    top: 59.5%;
    height: 34%;
    border-radius: calc(var(--w) * .01);
    background:
        linear-gradient(160deg, rgba(255, 255, 255, .07), transparent 45%),
        linear-gradient(180deg, #2a3039, #232830);
    box-shadow:
        inset 0 0 0 1px rgba(0, 0, 0, .45),
        inset 0 1px 0 rgba(255, 255, 255, .05),
        0 1px 0 rgba(255, 255, 255, .08);
}

/* front edge (thickness) */
.lip {
    position: absolute;
    left: var(--radius);
    right: var(--radius);
    top: 100%;
    height: var(--bt);
    transform-origin: 50% 0;
    transform: rotateX(-90deg);
    border-radius: 0 0 4px 4px;
    background: linear-gradient(180deg, #59616f 0%, #2f3540 18%, #1d2129 70%, #121519 100%);
}

.sideL,
.sideR {
    position: absolute;
    top: var(--radius);
    bottom: var(--radius);
    width: var(--bt);
    background: linear-gradient(90deg, #262b33, #3d4451);
}

.sideL { left: 0; transform-origin: 0 50%; transform: rotateY(90deg); }
.sideR { right: 0; transform-origin: 100% 50%; transform: rotateY(-90deg); }

/* ---------- Shadows ---------- */
.shadow {
    position: absolute;
    left: -2%;
    right: -2%;
    bottom: calc(-26% - var(--open) * 4%);
    height: 34%;
    border-radius: 50%;
    background: radial-gradient(closest-side, rgba(0, 0, 0, .7), rgba(0, 0, 0, .25) 60%, transparent);
    filter: blur(18px);
    z-index: -1;
}

.contactShadow {
    position: absolute;
    left: 4%;
    right: 4%;
    bottom: calc(-24% - var(--open) * 2%);
    height: 6%;
    border-radius: 50%;
    background: radial-gradient(closest-side, rgba(0, 0, 0, .95), transparent);
    filter: blur(5px);
    z-index: -1;
}

/* =========================================================
   Screen UI
   ========================================================= */
.topbar {
    display: flex;
    align-items: center;
    gap: 2cqw;
    height: 6.2cqw;
    padding: 0 2cqw;
    border-bottom: 1px solid rgba(255, 255, 255, .06);
    background: rgba(255, 255, 255, .02);
    flex-shrink: 0;
}

.dots { display: flex; gap: .9cqw; }
.dots i {
    width: 1.3cqw;
    height: 1.3cqw;
    border-radius: 50%;
    background: #ff5f57;
}
.dots i:nth-child(2) { background: #febc2e; }
.dots i:nth-child(3) { background: #28c840; }

.url {
    flex: 1;
    max-width: 46%;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: .8cqw;
    height: 3.6cqw;
    border-radius: 2cqw;
    background: rgba(255, 255, 255, .05);
    font-family: var(--font-mono);
    font-size: 1.6cqw;
    color: var(--text-muted);
}

.url svg { width: 1.4cqw; height: 1.4cqw; color: var(--accent-3); }
.topbarRight { width: 5cqw; }

.scenes {
    position: relative;
    flex: 1;
}

.boot,
.sceneSlot {
    position: absolute;
    inset: 0;
    opacity: 0;
    visibility: hidden;
    transform: translateY(3%) scale(.98);
    transition: opacity .6s var(--ease), transform .7s var(--ease), visibility .6s;
}

.sceneSlot.past { transform: translateY(-3%) scale(.98); }

.boot.on,
.sceneSlot.on {
    opacity: 1;
    visibility: visible;
    transform: none;
}

/* Boot screen */
.boot {
    display: grid;
    place-content: center;
    justify-items: center;
    gap: 3cqw;
}

.bootLogo {
    font-family: var(--font-display);
    font-weight: 700;
    font-size: 9cqw;
    letter-spacing: -0.04em;
    background: var(--gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    filter: drop-shadow(0 0 2cqw rgba(34, 211, 238, .4));
}

.bootBar {
    width: 22cqw;
    height: .6cqw;
    border-radius: 1cqw;
    background: rgba(255, 255, 255, .08);
    overflow: hidden;
}

.bootBar i {
    display: block;
    height: 100%;
    width: calc(var(--boot) * 100%);
    background: var(--gradient);
}

/* ---------- Scene: code ---------- */
.sceneCode {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-columns: 1.15fr 1fr;
}

.editor {
    border-right: 1px solid rgba(255, 255, 255, .06);
    background: rgba(0, 0, 0, .25);
    min-width: 0;
}

.tabs {
    display: flex;
    gap: .5cqw;
    padding: 1.2cqw 1.4cqw 0;
    font-family: var(--font-mono);
    font-size: 1.45cqw;
    color: var(--text-dim);
}

.tabs span { padding: .8cqw 1.4cqw; border-radius: .8cqw .8cqw 0 0; }
.tabActive { background: rgba(255, 255, 255, .05); color: var(--text) !important; }

.code {
    margin: 0;
    padding: 2cqw 1.6cqw;
    font-family: var(--font-mono);
    font-size: 1.62cqw;
    line-height: 2;
    color: #c9d1e0;
    overflow: hidden;
    white-space: pre;
}

.line {
    display: block;
    min-height: 1em;
    clip-path: inset(0 100% 0 0);
}

.on .line { animation: typeLine .5s steps(18, end) var(--d) forwards; }

@keyframes typeLine { to { clip-path: inset(0 0 0 0); } }

.ln {
    display: inline-block;
    width: 3cqw;
    color: #3a4356;
}

.tok_k { color: #c084fc; }
.tok_s { color: #34d399; }
.tok_f { color: #22d3ee; }
.tok_g { color: #818cf8; }
.tok_a { color: #fbbf24; }
.tok_t { color: #c9d1e0; }

.preview {
    position: relative;
    padding: 2.4cqw;
    display: flex;
    flex-direction: column;
    gap: 2cqw;
}

.pvHero {
    display: flex;
    flex-direction: column;
    gap: 1.2cqw;
    padding: 3cqw;
    border-radius: 1.6cqw;
    background: linear-gradient(135deg, rgba(34, 211, 238, .25), rgba(129, 140, 248, .2) 50%, rgba(192, 132, 252, .15));
    border: 1px solid rgba(255, 255, 255, .08);
    opacity: 0;
    transform: translateY(2cqw);
}

.pvTitle { height: 2.6cqw; width: 70%; border-radius: .6cqw; background: rgba(255, 255, 255, .85); }
.pvSub { height: 1.4cqw; width: 50%; border-radius: .6cqw; background: rgba(255, 255, 255, .35); }
.pvBtn { height: 3cqw; width: 11cqw; margin-top: .8cqw; border-radius: 2cqw; background: #fff; }

.pvCards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.4cqw; }

.pvCards span {
    height: 11cqw;
    border-radius: 1.2cqw;
    background: rgba(255, 255, 255, .05);
    border: 1px solid rgba(255, 255, 255, .08);
    opacity: 0;
    transform: translateY(2cqw);
}

.on .pvHero { animation: popUp .6s var(--ease) .6s forwards; }
.on .pvCards span { animation: popUp .5s var(--ease) var(--d) forwards; }

.pvBadge {
    align-self: flex-start;
    padding: .8cqw 1.6cqw;
    border-radius: 2cqw;
    font-family: var(--font-mono);
    font-size: 1.4cqw;
    color: var(--accent-3);
    background: rgba(52, 211, 153, .1);
    border: 1px solid rgba(52, 211, 153, .3);
    opacity: 0;
}

.on .pvBadge { animation: popUp .5s var(--ease) 1.6s forwards; }

@keyframes popUp { to { opacity: 1; transform: none; } }

/* ---------- Scene: UX ---------- */
.sceneUX {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-columns: 1fr 24cqw;
}

.canvas {
    position: relative;
    display: grid;
    place-items: center;
    background-image: radial-gradient(rgba(255, 255, 255, .09) 1px, transparent 1px);
    background-size: 2.4cqw 2.4cqw;
    overflow: hidden;
}

.frame {
    position: relative;
    width: 82%;
    padding: 2cqw;
    border-radius: 1.4cqw;
    background: #0e121a;
    border: 1px solid rgba(255, 255, 255, .1);
    display: flex;
    flex-direction: column;
    gap: 1.6cqw;
}

.wfNav { height: 2.4cqw; border-radius: .6cqw; border: 1px dashed rgba(255, 255, 255, .22); }

.wfHero {
    display: flex;
    flex-direction: column;
    gap: 1cqw;
    padding: 2.4cqw;
    border-radius: 1cqw;
    border: 1px dashed rgba(255, 255, 255, .22);
}

.wfHero span { height: 1.6cqw; border-radius: .5cqw; background: rgba(255, 255, 255, .12); }
.wfHero span:nth-child(1) { width: 60%; height: 2.4cqw; }
.wfHero span:nth-child(2) { width: 42%; }
.wfHero span:nth-child(3) { width: 16%; height: 2.6cqw; background: rgba(34, 211, 238, .5); }

.wfCards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.2cqw; }
.wfCards span { height: 8cqw; border-radius: 1cqw; border: 1px dashed rgba(255, 255, 255, .22); }

.selection {
    position: absolute;
    left: 1.4cqw;
    right: 1.4cqw;
    top: 5.4cqw;
    height: 14.2cqw;
    border: 1.5px solid var(--accent);
    border-radius: 1cqw;
    opacity: 0;
    transform: scale(.96);
}

.selection i {
    position: absolute;
    width: 1.2cqw;
    height: 1.2cqw;
    background: #fff;
    border: 1.5px solid var(--accent);
    border-radius: 2px;
}

.selection i:nth-child(1) { top: -.7cqw; left: -.7cqw; }
.selection i:nth-child(2) { top: -.7cqw; right: -.7cqw; }
.selection i:nth-child(3) { bottom: -.7cqw; left: -.7cqw; }
.selection i:nth-child(4) { bottom: -.7cqw; right: -.7cqw; }

.selection b {
    position: absolute;
    left: 50%;
    bottom: -3.4cqw;
    transform: translateX(-50%);
    padding: .3cqw 1cqw;
    border-radius: .6cqw;
    background: var(--accent);
    color: #05070a;
    font-family: var(--font-mono);
    font-size: 1.2cqw;
    font-weight: 500;
    white-space: nowrap;
}

.on .selection { animation: popUp .4s var(--ease) 1.25s forwards; }

.cursor {
    position: absolute;
    width: 3cqw;
    height: 3cqw;
    left: 80%;
    top: 80%;
    filter: drop-shadow(0 .4cqw .8cqw rgba(0, 0, 0, .6));
}

.on .cursor { animation: cursorPath 3.2s var(--ease) .3s both; }

@keyframes cursorPath {
    0% { left: 80%; top: 85%; }
    35% { left: 30%; top: 30%; }
    42% { left: 30%; top: 30%; transform: scale(.85); }
    48% { transform: none; }
    75% { left: 72%; top: 46%; }
    100% { left: 72%; top: 46%; }
}

.inspector {
    padding: 2cqw;
    border-left: 1px solid rgba(255, 255, 255, .06);
    background: rgba(0, 0, 0, .25);
    font-size: 1.4cqw;
}

.inspTitle {
    margin: 0 0 1.6cqw;
    font-family: var(--font-mono);
    font-size: 1.3cqw;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--text-dim);
}

.inspRow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1.1cqw 1.2cqw;
    margin-bottom: .9cqw;
    border-radius: .8cqw;
    background: rgba(255, 255, 255, .04);
    color: var(--text-muted);
    opacity: 0;
    transform: translateX(2cqw);
}

.inspRow b { color: var(--text); font-weight: 500; display: flex; align-items: center; gap: .6cqw; }
.inspRow em { width: 1.8cqw; height: 1.8cqw; border-radius: .4cqw; background: var(--gradient); }

.on .inspRow { animation: popUp .45s var(--ease) var(--d) forwards; }

.inspSwatches { display: flex; gap: .8cqw; margin-top: 1.6cqw; }
.inspSwatches span { width: 3cqw; height: 3cqw; border-radius: 50%; border: 1px solid rgba(255, 255, 255, .15); }

/* ---------- Scene: brand ---------- */
.sceneBrand {
    position: absolute;
    inset: 0;
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: 3cqw;
    padding: 3cqw 5cqw;
}

.logoCard {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2.4cqw;
    padding: 4cqw;
    border-radius: 2cqw;
    background: radial-gradient(80% 80% at 50% 30%, rgba(34, 211, 238, .12), transparent 70%), rgba(255, 255, 255, .03);
    border: 1px solid rgba(255, 255, 255, .08);
}

.logoMark { width: 20cqw; height: 20cqw; overflow: visible; }

.logoMark rect,
.logoMark path {
    fill: none;
    stroke: url(#brandGrad);
    stroke-width: 6;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
}

.logoMark rect { stroke-width: 3; opacity: .6; }

.on .logoMark rect { animation: svcDraw 1.1s var(--ease) .2s forwards; }
.on .logoMark path { animation: svcDraw 1s var(--ease) .7s forwards; }
.on .logoMark path + path { animation-delay: 1s; }

.brandName {
    font-family: var(--font-display);
    font-weight: 600;
    font-size: 2.6cqw;
    letter-spacing: -0.02em;
    opacity: 0;
}

.on .brandName { animation: popUp .5s var(--ease) 1.5s forwards; }

.brandSide { display: flex; flex-direction: column; gap: 3cqw; }

.palette {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 1cqw;
}

.palette span {
    position: relative;
    height: 13cqw;
    border-radius: 1.4cqw;
    border: 1px solid rgba(255, 255, 255, .1);
    opacity: 0;
    transform: translateY(3cqw) scale(.9);
}

.palette em {
    position: absolute;
    left: 50%;
    bottom: -2.6cqw;
    transform: translateX(-50%);
    font-family: var(--font-mono);
    font-style: normal;
    font-size: 1.05cqw;
    color: var(--text-dim);
}

.on .palette span { animation: popUp .55s cubic-bezier(.3, 1.4, .5, 1) var(--d) forwards; }

.typeSpec {
    display: flex;
    align-items: center;
    gap: 2.4cqw;
    margin-top: 2cqw;
    padding: 2cqw 2.4cqw;
    border-radius: 1.6cqw;
    background: rgba(255, 255, 255, .03);
    border: 1px solid rgba(255, 255, 255, .08);
    opacity: 0;
    transform: translateY(2cqw);
}

.on .typeSpec { animation: popUp .5s var(--ease) 1.1s forwards; }

.aa {
    font-family: var(--font-display);
    font-weight: 600;
    font-size: 7cqw;
    line-height: 1;
    background: var(--gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

.typeSpec b { display: block; font-family: var(--font-display); font-size: 2.2cqw; font-weight: 600; }
.typeSpec em { font-family: var(--font-mono); font-style: normal; font-size: 1.3cqw; color: var(--text-dim); }

/* ---------- Scene: app ---------- */
.sceneApp {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 3cqw;
    padding-bottom: 4cqw;
}

.phone {
    position: relative;
    width: 15cqw;
    height: 30cqw;
    padding: 2.6cqw 1.3cqw 1.3cqw;
    border-radius: 2.6cqw;
    background: #0e121a;
    border: 1.5px solid rgba(255, 255, 255, .16);
    display: flex;
    flex-direction: column;
    gap: 1cqw;
    opacity: 0;
    transform: translateY(5cqw) rotate(-4deg);
}

.phone:nth-child(3) { transform: translateY(5cqw) rotate(4deg); }

.phoneMain {
    width: 18cqw;
    height: 36cqw;
    border-color: rgba(34, 211, 238, .5);
    box-shadow: 0 2cqw 5cqw -2cqw rgba(34, 211, 238, .5);
    z-index: 1;
}

.on .phone { animation: phoneIn .7s cubic-bezier(.3, 1.3, .5, 1) var(--d) forwards; }
.on .phone:nth-child(1) { --r: -6deg; --y: 2cqw; }
.on .phone:nth-child(2) { --r: 0deg; --y: 0; }
.on .phone:nth-child(3) { --r: 6deg; --y: 2cqw; }

@keyframes phoneIn {
    to { opacity: 1; transform: translateY(var(--y)) rotate(var(--r)); }
}

.notch {
    position: absolute;
    top: .9cqw;
    left: 50%;
    width: 4.5cqw;
    height: 1cqw;
    margin-left: -2.25cqw;
    border-radius: 1cqw;
    background: #000;
}

.appHeader { height: 1.6cqw; width: 60%; border-radius: .5cqw; background: rgba(255, 255, 255, .5); }
.appCard { height: 30%; border-radius: 1.2cqw; background: linear-gradient(135deg, rgba(34, 211, 238, .6), rgba(129, 140, 248, .5), rgba(192, 132, 252, .45)); }
.appRow { height: 2.6cqw; border-radius: .8cqw; background: rgba(255, 255, 255, .07); }
.appRowShort { height: 2.6cqw; width: 70%; border-radius: .8cqw; background: rgba(255, 255, 255, .07); }

.appTab {
    margin-top: auto;
    height: 3cqw;
    border-radius: 1.2cqw;
    background: rgba(255, 255, 255, .06);
    border-top: 1px solid rgba(255, 255, 255, .06);
}

.toast {
    position: absolute;
    top: 4cqw;
    right: 5cqw;
    z-index: 2;
    display: flex;
    align-items: center;
    gap: 1.4cqw;
    padding: 1.4cqw 2cqw;
    border-radius: 1.6cqw;
    background: rgba(14, 18, 26, .92);
    border: 1px solid rgba(52, 211, 153, .35);
    box-shadow: 0 2cqw 4cqw -2cqw rgba(0, 0, 0, .8);
    opacity: 0;
    transform: translateX(4cqw);
}

.on .toast { animation: popUp .6s cubic-bezier(.3, 1.3, .5, 1) 1.2s forwards; }

.toastIcon {
    display: grid;
    place-items: center;
    width: 3.2cqw;
    height: 3.2cqw;
    border-radius: 50%;
    background: rgba(52, 211, 153, .15);
    color: var(--accent-3);
    font-size: 1.8cqw;
}

.toast b { display: block; font-size: 1.6cqw; font-weight: 600; }
.toast em { font-style: normal; font-family: var(--font-mono); font-size: 1.2cqw; color: var(--text-dim); }

.terminal {
    position: absolute;
    left: 4cqw;
    bottom: 3cqw;
    padding: 1cqw 1.6cqw;
    border-radius: 1cqw;
    background: rgba(0, 0, 0, .5);
    border: 1px solid rgba(255, 255, 255, .08);
    font-family: var(--font-mono);
    font-size: 1.4cqw;
    color: var(--text-muted);
    clip-path: inset(0 100% 0 0);
}

.terminal span { color: var(--accent-3); margin-right: .6cqw; }
.on .terminal { animation: typeLine .9s steps(22, end) .6s forwards; }

/* =========================================================
   Caption
   ========================================================= */
.caption {
    position: relative;
    z-index: 3;
    width: min(620px, 92vw);
    text-align: center;
    opacity: 0;
    transform: translateY(20px);
    transition: opacity .6s var(--ease), transform .6s var(--ease);
    min-height: 170px;
}

.captionOn { opacity: 1; transform: none; }

.captionHead {
    display: inline-flex;
    align-items: center;
    gap: 12px;
}

.captionIcon {
    display: grid;
    place-items: center;
    width: 46px;
    height: 46px;
    border-radius: 14px;
    background: radial-gradient(circle at 30% 20%, rgba(34, 211, 238, .16), transparent 70%), rgba(255, 255, 255, .03);
    border: 1px solid rgba(34, 211, 238, .25);
}

.captionMeta {
    font-family: var(--font-mono);
    font-size: 12.5px;
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--text-dim);
}

.captionTitle {
    margin: 14px 0 8px;
    font-size: clamp(1.5rem, 3vw, 2.2rem);
    font-weight: 600;
    letter-spacing: -0.03em;
    animation: captionIn .6s var(--ease) both;
}

.captionText {
    margin: 0 auto;
    max-width: 520px;
    font-size: 15.5px;
    line-height: 1.65;
    color: var(--text-muted);
    animation: captionIn .6s var(--ease) .08s both;
}

@keyframes captionIn {
    from { opacity: 0; transform: translateY(12px); filter: blur(6px); }
    to { opacity: 1; transform: none; filter: none; }
}

.rail {
    display: flex;
    gap: 6px;
    width: 200px;
    margin: 20px auto 0;
}

.rail span {
    position: relative;
    flex: 1;
    height: 3px;
    border-radius: 3px;
    background: rgba(255, 255, 255, .1);
    overflow: hidden;
}

.rail span::after {
    content: '';
    position: absolute;
    inset: 0;
    transform-origin: 0 50%;
    transform: scaleX(var(--fill));
    background: var(--gradient);
}

/* ---------- Responsive ---------- */
@media (max-width: 767.98px) {
    .wrap {
        height: 460vh;
        --w: min(94vw, calc((100vh - 320px) * 1.1));
    }
    .stage { gap: 18px; }
    .intro { top: 13vh; }
    .captionText { font-size: 14px; }
    .caption { min-height: 190px; }
}

@media (prefers-reduced-motion: reduce) {
    .sceneSlot, .boot { transition: none; }
}

/* local copies — CSS Modules scopes keyframe names */
@keyframes svcDraw { to { stroke-dashoffset: 0; } }
