/* ---------- Filter bar ---------- */
.filterBar {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 32px;
}

.pills {
    position: relative;
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin: 0;
    padding: 5px;
    list-style: none;
    border: 1px solid var(--border);
    border-radius: 999px;
    background: var(--surface);
}

.pill {
    padding: 8px 18px;
    border: 0;
    border-radius: 999px;
    background: transparent;
    color: var(--text-muted);
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: color .25s, background .25s;
}

.pill:hover { color: var(--text); }

.pill { position: relative; z-index: 1; }
.pill.active { color: var(--bg); }

/* highlight that slides between filters */
.pillIndicator {
    position: absolute;
    top: 5px;
    bottom: 5px;
    left: 0;
    border-radius: 999px;
    background: var(--text);
    box-shadow: 0 6px 20px -6px rgba(34, 211, 238, .5);
    transition: transform .45s var(--ease), width .45s var(--ease), opacity .3s;
    pointer-events: none;
}

.count {
    margin-left: auto;
    font-family: var(--font-mono);
    font-size: 13px;
    color: var(--text-dim);
}

/* Mobile dropdown */
.dropdown {
    display: none;
    position: relative;
    flex: 1;
}

.dropdownButton {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 18px;
    border: 1px solid var(--border-strong);
    border-radius: 14px;
    background: var(--surface);
    color: var(--text);
    font-size: 15px;
    cursor: pointer;
}

.dropdownLabel {
    color: var(--text-dim);
    font-family: var(--font-mono);
    font-size: 12px;
    margin-right: 4px;
}

.dropdownIcon { transition: transform .3s var(--ease); }
.rotated { transform: rotate(180deg); }

.dropdownMenu {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    right: 0;
    z-index: 20;
    margin: 0;
    padding: 6px;
    list-style: none;
    border: 1px solid var(--border-strong);
    border-radius: 14px;
    background: #0e121a;
    box-shadow: 0 20px 50px -10px rgba(0, 0, 0, 0.7);
    max-height: 320px;
    overflow-y: auto;
    animation: menuIn .25s var(--ease);
}

@keyframes menuIn {
    from { opacity: 0; transform: translateY(-6px); }
    to { opacity: 1; transform: none; }
}

.dropdownItem {
    width: 100%;
    text-align: left;
    padding: 10px 14px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: var(--text-muted);
    font-size: 15px;
    cursor: pointer;
}

.dropdownItem:hover { background: var(--surface-2); color: var(--text); }
.dropdownActive { color: var(--accent); background: rgba(34, 211, 238, 0.08); }

/* ---------- Grid ----------
   6 projects per page → 3 columns × 2 rows on desktop
   (2 columns on tablet, 1 on phones) */
.grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
}

.card {
    position: relative;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    cursor: pointer;
    outline: none;
}

.card.in:hover,
.card.in:focus-visible {
    transform: translateY(-6px);
    border-color: transparent;
}

.card:focus-visible { box-shadow: 0 0 0 2px var(--accent); }


/* ---------- Image ---------- */
.imageContainer {
    position: relative;
    aspect-ratio: 16 / 10;
    margin: 8px 8px 0;
    border-radius: 12px;
    overflow: hidden;
    background: linear-gradient(135deg, #121826, #0b0f17);
    isolation: isolate;
}


.image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: top center;
    transition: transform 1s var(--ease), filter .6s;
}

.card:hover .image,
.card:focus-visible .image {
    transform: scale(1.06);
    filter: brightness(.55) saturate(1.1);
}

/* subtle bottom shade so the number reads */
.imageContainer::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, transparent 60%, rgba(7, 9, 13, .55));
    pointer-events: none;
}

.number {
    position: absolute;
    left: 14px;
    bottom: 10px;
    z-index: 2;
    font-family: var(--font-mono);
    font-size: 12px;
    color: rgba(255, 255, 255, .7);
    letter-spacing: .1em;
}

/* frosted CTA revealed on hover */
.hoverCta {
    position: absolute;
    left: 50%;
    top: 50%;
    z-index: 2;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 12px 20px;
    border-radius: 999px;
    background: rgba(255, 255, 255, .14);
    border: 1px solid rgba(255, 255, 255, .25);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    color: #fff;
    font-size: 14px;
    font-weight: 600;
    white-space: nowrap;
    opacity: 0;
    transform: translate(-50%, -30%) scale(.92);
    transition: opacity .4s var(--ease), transform .5s var(--ease);
    pointer-events: none;
}

.card:hover .hoverCta,
.card:focus-visible .hoverCta {
    opacity: 1;
    transform: translate(-50%, -50%);
}

/* ---------- Info ---------- */
.info {
    position: relative;
    display: flex;
    flex-direction: column;
    padding: 18px 22px 22px;
}


.meta {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 12px;
    padding-right: 44px; /* room for the arrow */
}

.category {
    padding: 4px 10px;
    border-radius: 999px;
    font-family: var(--font-mono);
    font-size: 11px;
    color: var(--accent);
    background: rgba(34, 211, 238, .08);
    border: 1px solid rgba(34, 211, 238, .25);
}


.date {
    font-family: var(--font-mono);
    font-size: 11.5px;
    color: var(--text-dim);
}

.name {
    margin: 0;
    font-size: 18px;
    font-weight: 600;
    line-height: 1.3;
    letter-spacing: -0.02em;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}


.description {
    margin: 8px 0 0;
    font-size: 14px;
    line-height: 1.6;
    color: var(--text-muted);
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}




.arrow {
    position: absolute;
    top: 14px;
    right: 18px;
    width: 34px;
    height: 34px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    border: 1px solid var(--border-strong);
    color: var(--text);
    transition: background .35s var(--ease), color .35s, border-color .35s, transform .45s var(--ease);
}


.card:hover .arrow,
.card:focus-visible .arrow {
    background: var(--accent);
    border-color: var(--accent);
    color: #05070a;
    transform: rotate(45deg);
}

/* Skeleton */
.skeleton {
    height: 380px;
    border-radius: var(--radius);
    border: 1px solid var(--border);
    background: linear-gradient(100deg, rgba(255, 255, 255, 0.02) 30%, rgba(255, 255, 255, 0.06) 50%, rgba(255, 255, 255, 0.02) 70%);
    background-size: 300% 100%;
    animation: shimmer 1.6s linear infinite;
}

@keyframes shimmer {
    from { background-position: 100% 0; }
    to { background-position: -100% 0; }
}

.empty {
    padding: 80px 20px;
    text-align: center;
    color: var(--text-muted);
    border: 1px dashed var(--border-strong);
    border-radius: var(--radius);
}

/* ---------- Pagination ---------- */
.pagination {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    gap: 6px;
    margin-top: 48px;
}

.pageBtn,
.pageNumber {
    min-width: 42px;
    height: 42px;
    padding: 0 12px;
    display: grid;
    place-items: center;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: var(--surface);
    color: var(--text-muted);
    font-family: var(--font-mono);
    font-size: 14px;
    cursor: pointer;
    transition: all .25s var(--ease);
}

.pageBtn:hover:not(:disabled),
.pageNumber:hover {
    color: var(--text);
    border-color: var(--border-strong);
    transform: translateY(-2px);
}

.pageBtn:disabled { opacity: .35; cursor: not-allowed; }

.activePage {
    color: var(--bg);
    background: var(--accent);
    border-color: var(--accent);
    box-shadow: 0 8px 24px -8px rgba(34, 211, 238, 0.7);
}

.activePage:hover { color: var(--bg); }

.dots { color: var(--text-dim); padding: 0 4px; }

.pageInfo {
    width: 100%;
    text-align: center;
    margin-top: 14px;
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--text-dim);
}

/* ---------- Responsive ---------- */
@media (max-width: 991.98px) {
    .grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 767.98px) {
    .pills { display: none; }
    .dropdown { display: block; }
    .count { display: none; }
}

@media (max-width: 575.98px) {
    .grid { grid-template-columns: 1fr; }
}
