.header {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 1000;
    padding: 18px 20px;
    transition: padding .4s var(--ease);
    animation: dropIn .9s var(--ease) both;
}

@keyframes dropIn {
    from { opacity: 0; transform: translateY(-24px); }
    to { opacity: 1; transform: none; }
}

.nav {
    max-width: 1240px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    gap: 24px;
    padding: 10px 12px 10px 20px;
    border-radius: 999px;
    border: 1px solid transparent;
    transition: background .4s var(--ease), border-color .4s var(--ease), box-shadow .4s var(--ease), max-width .5s var(--ease);
}

.scrolled { padding-top: 12px; }

.scrolled .nav {
    max-width: 1080px;
    background: rgba(11, 14, 20, 0.72);
    border-color: var(--border);
    box-shadow: 0 10px 40px -10px rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(16px) saturate(140%);
    -webkit-backdrop-filter: blur(16px) saturate(140%);
}

.brand {
    background: none;
    border: 0;
    padding: 0;
    display: flex;
    cursor: pointer;
}

.brand img {
    height: 38px;
    width: auto;
    transition: transform .3s var(--ease), opacity .3s;
}

.brand:hover img { transform: scale(1.04); }

.links {
    display: flex;
    align-items: center;
    gap: 2px;
    margin: 0 auto;
    padding: 0;
    list-style: none;
}

.link {
    position: relative;
    background: none;
    border: 0;
    padding: 8px 14px;
    border-radius: 999px;
    color: var(--text-muted);
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: color .25s, background .25s;
}

.link:hover { color: var(--text); background: var(--surface-2); }

.link.active { color: var(--text); }

.link.active::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: 2px;
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--accent);
    box-shadow: 0 0 10px var(--accent);
    transform: translateX(-50%);
}

.link:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

.cta { flex-shrink: 0; }

.mobileCta { display: none; }

.toggler {
    display: none;
    width: 42px;
    height: 42px;
    border-radius: 50%;
    border: 1px solid var(--border-strong);
    background: var(--surface);
    position: relative;
    cursor: pointer;
    margin-left: auto;
}

.toggler span {
    position: absolute;
    left: 12px;
    right: 12px;
    height: 1.5px;
    background: var(--text);
    transition: transform .35s var(--ease), top .35s var(--ease);
}

.toggler span:first-child { top: 16px; }
.toggler span:last-child { top: 24px; }

.togglerOpen span:first-child { top: 20px; transform: rotate(45deg); }
.togglerOpen span:last-child { top: 20px; transform: rotate(-45deg); }

@media (max-width: 991.98px) {
    .header { padding: 12px 16px; }

    .nav {
        background: rgba(11, 14, 20, 0.72);
        border-color: var(--border);
        backdrop-filter: blur(16px);
        -webkit-backdrop-filter: blur(16px);
        border-radius: 22px;
    }

    .cta { display: none; }
    .toggler { display: block; }

    .links {
        position: absolute;
        top: calc(100% - 4px);
        left: 16px;
        right: 16px;
        flex-direction: column;
        align-items: stretch;
        gap: 4px;
        padding: 14px;
        border-radius: 22px;
        background: rgba(11, 14, 20, 0.95);
        border: 1px solid var(--border);
        backdrop-filter: blur(16px);
        -webkit-backdrop-filter: blur(16px);
        opacity: 0;
        visibility: hidden;
        transform: translateY(-10px) scale(.98);
        transition: opacity .3s var(--ease), transform .3s var(--ease), visibility .3s;
    }

    .links.open {
        opacity: 1;
        visibility: visible;
        transform: none;
    }

    .links li {
        opacity: 0;
        transform: translateY(8px);
        transition: opacity .4s var(--ease), transform .4s var(--ease);
        transition-delay: calc(var(--i) * 40ms);
    }

    .links.open li { opacity: 1; transform: none; }

    .link {
        width: 100%;
        text-align: left;
        padding: 12px 16px;
        font-size: 16px;
        border-radius: 12px;
    }

    .link.active { background: var(--surface-2); }
    .link.active::after { left: auto; right: 16px; top: 50%; bottom: auto; transform: translateY(-50%); }

    .mobileCta { display: block; margin-top: 8px; }
    .mobileCta button { width: 100%; justify-content: center; }
}
